{
  "name": "BiblioTier - Ultimate Book Ranking",
  "description": "An interactive book tier ranking dashboard with custom themes, Google Books search, and AI-powered book cover animation using Veo.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type TierId = 'TBR' | 'GOD' | 'A' | 'B' | 'C' | 'DNF';

export type BookFormat = 'Audiobook' | 'Physical Book' | 'E-reader';

export interface Book {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
  tier: TierId;
  dateStarted?: string;
  dateFinished?: string;
  format: BookFormat;
  comments: string;
  dnfProgress: number; // 0-100
}

export interface ThemeColors {
  TBR: string;
  GOD: string;
  A: string;
  B: string;
  C: string;
  DNF: string;
  background: string;
  accent: string;
  text: string;
}

export type ThemePreset = 'Dark Academia' | 'Cyberpunk' | 'Pastel Dream' | 'Custom';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Book as BookIcon, 
  Trash2, 
  Search, 
  Settings, 
  Layout, 
  Plus, 
  X, 
  BookOpen, 
  Headphones, 
  Monitor, 
  ChevronDown,
  Sparkles,
  Loader2,
  Video
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors, BookFormat } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);

  // Persistence
  useEffect(() => {
    const savedBooks = localStorage.getItem('biblio_books');
    const savedTheme = localStorage.getItem('biblio_theme');
    const savedColors = localStorage.getItem('biblio_colors');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
  }, []);

  useEffect(() => {
    localStorage.setItem('biblio_books', JSON.stringify(books));
    localStorage.setItem('biblio_theme', activeTheme);
    localStorage.setItem('biblio_colors', JSON.stringify(customColors));
  }, [books, activeTheme, customColors]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  const addBook = useCallback((newBook: Omit<Book, 'id' | 'tier' | 'format' | 'comments' | 'dnfProgress'>) => {
    const book: Book = {
      ...newBook,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      format: 'Physical Book',
      comments: '',
      dnfProgress: 0,
    };
    setBooks(prev => [...prev, book]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      if (book.tier === 'DNF' && book.dnfProgress > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveBook = (id: string, newTier: TierId) => {
    setBooks(prev => prev.map(b => b.id === id ? { ...b, tier: newTier } : b));
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      {/* Header */}
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookIcon className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">BiblioTier</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-xs uppercase font-semibold opacity-70">Total Read</span>
            <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => setIsVeoOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Animate Cover (AI)"
            >
              <Video className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsThemeOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Theme Settings"
            >
              <Settings className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-4 py-2 rounded-full text-white font-bold transition-transform hover:scale-105 active:scale-95 shadow-lg"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-5 h-5" />
              <span className="hidden sm:inline">Add Book</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Board */}
      <main className="max-w-7xl mx-auto px-4 py-8 space-y-6">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            className="flex flex-col sm:flex-row min-h-[140px] rounded-xl overflow-hidden shadow-sm border transition-all hover:shadow-md"
            style={{ backgroundColor: `${currentColors[tier.id]}11`, borderColor: `${currentColors[tier.id]}44` }}
          >
            {/* Tier Label */}
            <div 
              className="sm:w-32 flex flex-col items-center justify-center p-4 text-white font-black text-center"
              style={{ backgroundColor: currentColors[tier.id] }}
            >
              <span className="text-lg leading-tight uppercase">{tier.label}</span>
              <div className="mt-2 px-2 py-0.5 rounded-full bg-black/20 text-xs font-bold">
                {booksByTier[tier.id].length} Books
              </div>
            </div>

            {/* Books Container */}
            <div className="flex-1 p-4 flex flex-wrap gap-4 items-start content-start">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  className="relative group w-24 sm:w-32 cursor-pointer"
                  onClick={() => setSelectedBook(book)}
                >
                  <img 
                    src={book.coverUrl || 'https://picsum.photos/120/180'} 
                    alt={book.title}
                    className="w-full h-36 sm:h-48 object-cover rounded shadow-md border-2 border-transparent group-hover:border-white transition-all transform group-hover:scale-105"
                  />
                  <div className="mt-1">
                    <p className="text-[10px] sm:text-xs font-bold truncate leading-none">{book.title}</p>
                    <p className="text-[9px] sm:text-[10px] opacity-70 truncate">{book.author}</p>
                  </div>

                  {/* Quick Mover */}
                  <div 
                    className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity bg-black/70 rounded-full p-1"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <select 
                      className="bg-transparent text-[10px] text-white outline-none cursor-pointer"
                      value={book.tier}
                      onChange={(e) => moveBook(book.id, e.target.value as TierId)}
                    >
                      {TIERS.map(t => (
                        <option key={t.id} value={t.id} className="text-black">{t.label}</option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full h-full flex items-center justify-center opacity-20 italic pointer-events-none">
                  Empty Row
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {/* Modals */}
      {isSearchOpen && (
        <SearchPanel 
          onClose={() => setIsSearchOpen(false)} 
          onAdd={addBook}
          accentColor={currentColors.accent}
        />
      )}

      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook}
          onDelete={deleteBook}
          accentColor={currentColors.accent}
        />
      )}

      {isThemeOpen && (
        <ThemeManager 
          activeTheme={activeTheme}
          setActiveTheme={setActiveTheme}
          customColors={customColors}
          setCustomColors={setCustomColors}
          onClose={() => setIsThemeOpen(false)}
        />
      )}

      {isVeoOpen && (
        <VeoAnimator 
          onClose={() => setIsVeoOpen(false)}
          accentColor={currentColors.accent}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, X, Loader2, Plus } from 'lucide-react';

interface SearchResult {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
}

interface SearchPanelProps {
  onClose: () => void;
  onAdd: (book: Omit<any, 'id' | 'tier' | 'format' | 'comments' | 'dnfProgress'>) => void;
  accentColor: string;
}

const SearchPanel: React.FC<SearchPanelProps> = ({ onClose, onAdd, accentColor }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(`https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(query)}&maxResults=10`);
      const data = await response.json();

      const formatted = (data.items || []).map((item: any) => ({
        id: item.id,
        title: item.volumeInfo.title,
        author: item.volumeInfo.authors?.[0] || 'Unknown Author',
        coverUrl: item.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:') || '',
      }));

      setResults(formatted);
    } catch (error) {
      console.error('Search failed', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-4 border-b flex items-center justify-between">
          <h2 className="text-xl font-bold text-gray-800">Add New Book</h2>
          <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSearch} className="p-4 bg-gray-50">
          <div className="relative">
            <input 
              type="text" 
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by title, author, or ISBN..."
              className="w-full pl-12 pr-4 py-3 rounded-xl border focus:ring-2 outline-none transition-all shadow-inner"
              style={{ borderColor: accentColor }}
              autoFocus
            />
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-6 h-6 text-gray-400" />
            <button 
              type="submit"
              className="absolute right-2 top-1/2 -translate-y-1/2 px-4 py-1.5 rounded-lg text-white font-semibold transition-opacity"
              style={{ backgroundColor: accentColor }}
              disabled={loading}
            >
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Search'}
            </button>
          </div>
        </form>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {results.map(book => (
            <div 
              key={book.id} 
              className="flex items-center gap-4 p-3 rounded-xl border hover:bg-gray-50 group transition-colors"
            >
              <img 
                src={book.coverUrl || 'https://picsum.photos/60/90'} 
                alt={book.title} 
                className="w-16 h-24 object-cover rounded shadow"
              />
              <div className="flex-1">
                <h3 className="font-bold text-gray-900 leading-tight">{book.title}</h3>
                <p className="text-sm text-gray-500">{book.author}</p>
              </div>
              <button 
                onClick={() => onAdd(book)}
                className="p-3 rounded-full text-white shadow-md transform hover:scale-110 active:scale-95 transition-all"
                style={{ backgroundColor: accentColor }}
              >
                <Plus className="w-6 h-6" />
              </button>
            </div>
          ))}
          {!loading && results.length === 0 && query && (
            <div className="text-center py-12 text-gray-400">
              No books found for "{query}"
            </div>
          )}
          {!query && (
            <div className="text-center py-12 text-gray-400">
              Type something above to start searching!
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SearchPanel;

import React, { useState } from 'react';
import { X, Headphones, Book as BookIcon, Monitor, Trash2, Calendar, MessageSquare, Percent } from 'lucide-react';
import { Book, BookFormat, TierId } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book });

  const formats: { value: BookFormat; icon: any }[] = [
    { value: 'Audiobook', icon: Headphones },
    { value: 'Physical Book', icon: BookIcon },
    { value: 'E-reader', icon: Monitor },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        {/* Header */}
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="px-3 py-1 rounded-full text-xs font-bold uppercase text-white" style={{ backgroundColor: accentColor }}>
              {editedBook.tier}
            </span>
            <h2 className="text-lg font-bold truncate max-w-md text-gray-800">Edit Details</h2>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => { if(window.confirm('Delete this book?')) onDelete(book.id) }}
              className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
              <X className="w-6 h-6 text-gray-400" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-8 flex flex-col md:flex-row gap-8">
          {/* Cover Section */}
          <div className="w-full md:w-64 flex flex-col gap-4">
            <img 
              src={book.coverUrl || 'https://picsum.photos/250/375'} 
              alt={book.title} 
              className="w-full aspect-[2/3] object-cover rounded-xl shadow-lg"
            />
            <div className="space-y-1">
              <h1 className="text-xl font-black text-gray-900 leading-tight">{book.title}</h1>
              <p className="text-gray-600 font-medium">{book.author}</p>
            </div>

            <div className="space-y-3">
               <label className="block text-xs font-bold uppercase text-gray-400">Format</label>
               <div className="flex gap-2">
                 {formats.map(f => (
                   <button
                    key={f.value}
                    onClick={() => setEditedBook(prev => ({ ...prev, format: f.value }))}
                    className={`flex-1 flex flex-col items-center gap-1 p-2 rounded-lg border-2 transition-all ${editedBook.format === f.value ? 'bg-blue-50 border-blue-500' : 'border-gray-100 hover:border-gray-200'}`}
                    style={{ borderColor: editedBook.format === f.value ? accentColor : '' }}
                   >
                     <f.icon className={`w-6 h-6 ${editedBook.format === f.value ? 'text-blue-500' : 'text-gray-400'}`} style={{ color: editedBook.format === f.value ? accentColor : '' }} />
                     <span className="text-[10px] font-bold">{f.value.split(' ')[0]}</span>
                   </button>
                 ))}
               </div>
            </div>
          </div>

          {/* Details Section */}
          <div className="flex-1 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
                  <Calendar className="w-3 h-3" /> Date Started
                </label>
                <input 
                  type="date" 
                  value={editedBook.dateStarted || ''}
                  onChange={e => setEditedBook(prev => ({ ...prev, dateStarted: e.target.value }))}
                  className="w-full p-2 rounded-lg border border-gray-200 focus:border-blue-400 outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
                  <Calendar className="w-3 h-3" /> Date Finished
                </label>
                <input 
                  type="date" 
                  value={editedBook.dateFinished || ''}
                  onChange={e => setEditedBook(prev => ({ ...prev, dateFinished: e.target.value }))}
                  className="w-full p-2 rounded-lg border border-gray-200 focus:border-blue-400 outline-none"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
                <Layout className="w-3 h-3" /> Current Tier
              </label>
              <select 
                value={editedBook.tier}
                onChange={e => setEditedBook(prev => ({ ...prev, tier: e.target.value as TierId }))}
                className="w-full p-2 rounded-lg border border-gray-200 focus:border-blue-400 outline-none font-bold"
              >
                {TIERS.map(t => (
                  <option key={t.id} value={t.id}>{t.label}</option>
                ))}
              </select>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="space-y-3 bg-red-50 p-4 rounded-xl border border-red-100">
                <label className="flex items-center justify-between text-xs font-bold uppercase text-red-400">
                  <div className="flex items-center gap-2">
                    <Percent className="w-3 h-3" /> Reading Progress
                  </div>
                  <span>{editedBook.dnfProgress}%</span>
                </label>
                <input 
                  type="range" 
                  min="0" 
                  max="100" 
                  value={editedBook.dnfProgress}
                  onChange={e => setEditedBook(prev => ({ ...prev, dnfProgress: parseInt(e.target.value) }))}
                  className="w-full h-2 bg-red-200 rounded-lg appearance-none cursor-pointer accent-red-500"
                />
                <p className="text-[10px] text-red-400 italic">
                  {editedBook.dnfProgress > 80 
                    ? "✓ Over 80% read: Counts toward 'Total Books Read'." 
                    : "× Under 80% read: Does not count toward total."}
                </p>
              </div>
            )}

            <div className="space-y-2">
              <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
                <MessageSquare className="w-3 h-3" /> Comments & Notes
              </label>
              <textarea 
                value={editedBook.comments}
                onChange={e => setEditedBook(prev => ({ ...prev, comments: e.target.value }))}
                placeholder="Write your thoughts here..."
                rows={5}
                className="w-full p-4 rounded-xl border border-gray-200 focus:border-blue-400 outline-none resize-none shadow-inner"
              />
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-6 py-2 rounded-full font-bold text-gray-500 hover:bg-gray-100 transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={() => onSave(editedBook)}
            className="px-8 py-2 rounded-full font-bold text-white shadow-lg transition-transform hover:scale-105 active:scale-95"
            style={{ backgroundColor: accentColor }}
          >
            Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

import React from 'react';
import { X, Palette, Pipette } from 'lucide-react';
import { ThemePreset, ThemeColors, TierId } from '../types';
import { THEME_PRESETS, TIERS } from '../constants';

interface ThemeManagerProps {
  activeTheme: ThemePreset;
  setActiveTheme: (theme: ThemePreset) => void;
  customColors: ThemeColors;
  setCustomColors: (colors: ThemeColors) => void;
  onClose: () => void;
}

const ThemeManager: React.FC<ThemeManagerProps> = ({ 
  activeTheme, 
  setActiveTheme, 
  customColors, 
  setCustomColors, 
  onClose 
}) => {
  const presets: ThemePreset[] = ['Dark Academia', 'Cyberpunk', 'Pastel Dream', 'Custom'];

  const handleCustomColorChange = (tier: keyof ThemeColors, value: string) => {
    setCustomColors({ ...customColors, [tier]: value });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-lg overflow-hidden shadow-2xl flex flex-col">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Palette className="w-6 h-6 text-gray-700" />
            <h2 className="text-xl font-bold text-gray-800">Visual Customization</h2>
          </div>
          <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-gray-500" />
          </button>
        </div>

        <div className="p-6 space-y-8 overflow-y-auto max-h-[70vh]">
          {/* Preset Selector */}
          <div className="space-y-4">
            <label className="text-xs font-black uppercase tracking-widest text-gray-400">Preset Themes</label>
            <div className="grid grid-cols-2 gap-3">
              {presets.map(p => (
                <button
                  key={p}
                  onClick={() => setActiveTheme(p)}
                  className={`p-3 rounded-xl border-2 transition-all text-left flex flex-col gap-2 ${activeTheme === p ? 'border-blue-500 bg-blue-50 ring-2 ring-blue-500/20' : 'border-gray-100 hover:border-gray-200'}`}
                >
                  <span className={`font-bold ${activeTheme === p ? 'text-blue-600' : 'text-gray-700'}`}>{p}</span>
                  <div className="flex gap-1">
                    {TIERS.slice(0, 4).map(t => (
                      <div 
                        key={t.id} 
                        className="w-4 h-4 rounded-full border border-black/10 shadow-sm"
