            <div className="flex-1 rounded-2xl bg-black flex items-center justify-center relative shadow-inner">
              {videoUrl ? (
                <video src={videoUrl} controls autoPlay loop className="max-w-full max-h-full rounded-xl" />
              ) : (
                <div className="text-center p-8 space-y-4">
                  <div className="w-16 h-16 bg-gray-800 rounded-full flex items-center justify-center mx-auto">
                    <Play className="w-8 h-8 text-gray-600 ml-1" />
                  </div>
                  <p className="text-gray-500 font-bold uppercase text-xs tracking-widest">Preview Area</p>
                  {status && (
                    <div className="bg-gray-900 text-purple-400 p-3 rounded-lg text-[10px] font-mono animate-pulse border border-purple-900/50">
                      {status}
                    </div>
                  )}
                </div>
              )}
            </div>

            {videoUrl && (
              <div className="bg-green-50 p-4 rounded-xl border border-green-100 flex items-center justify-between">
                <div>
                  <p className="font-bold text-green-800">Success!</p>
                  <p className="text-xs text-green-600">Video generated successfully.</p>
                </div>
                <button 
                  onClick={() => {
                    const a = document.createElement('a');
                    a.href = videoUrl;
                    a.download = 'book-animation.mp4';
                    a.click();
                  }}
                  className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors flex items-center gap-2"
                >
                  Download <ExternalLink className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default VeoAnimator;

export type TierId = 'TBR' | 'GOD' | 'A' | 'B' | 'C' | 'DNF';

export type BookFormat = 'Audiobook' | 'Physical Book' | 'E-reader';

export interface ReadingSession {
  id: string;
  startDate: string;
  endDate: string;
  format: BookFormat;
}

export interface Book {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
  tier: TierId;
  sessions: ReadingSession[];
  comments: string;
  dnfProgress: number; // 0-100
}

export interface ThemeColors {
  TBR: string;
  GOD: string;
  A: string;
  B: string;
  C: string;
  DNF: string;
  background: string;
  accent: string;
  text: string;
}

export type ThemePreset = 'Dark Academia' | 'Cyberpunk' | 'Pastel Dream' | 'Custom';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Book as BookIcon, 
  Settings, 
  Plus, 
  Video,
  Volume2
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors, ReadingSession } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);

  // Persistence & Migration
  useEffect(() => {
    const savedBooks = localStorage.getItem('biblio_books');
    const savedTheme = localStorage.getItem('biblio_theme');
    const savedColors = localStorage.getItem('biblio_colors');

    if (savedBooks) {
      const parsed: any[] = JSON.parse(savedBooks);
      // Migrate old data structure to new sessions-based structure
      const migrated = parsed.map(b => {
        if (!b.sessions) {
          return {
            ...b,
            sessions: b.dateStarted || b.dateFinished ? [{
              id: Math.random().toString(36).substr(2, 9),
              startDate: b.dateStarted || '',
              endDate: b.dateFinished || '',
              format: b.format || 'Physical Book'
            }] : []
          };
        }
        return b;
      });
      setBooks(migrated);
    }
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
  }, []);

  useEffect(() => {
    localStorage.setItem('biblio_books', JSON.stringify(books));
    localStorage.setItem('biblio_theme', activeTheme);
    localStorage.setItem('biblio_colors', JSON.stringify(customColors));
  }, [books, activeTheme, customColors]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  const addBook = useCallback((newBook: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress'>) => {
    const book: Book = {
      ...newBook,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
    };
    setBooks(prev => [...prev, book]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      if (book.tier === 'DNF' && book.dnfProgress > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveBook = (id: string, newTier: TierId) => {
    setBooks(prev => prev.map(b => b.id === id ? { ...b, tier: newTier } : b));
  };

  // Drag and Drop Handlers
  const handleDragStart = (id: string) => {
    setDraggedBookId(id);
  };

  const handleDragOver = (e: React.DragEvent, tierId: TierId) => {
    e.preventDefault();
    setDragOverTier(tierId);
  };

  const handleDrop = (e: React.DragEvent, tierId: TierId) => {
    e.preventDefault();
    if (draggedBookId) {
      moveBook(draggedBookId, tierId);
    }
    setDraggedBookId(null);
    setDragOverTier(null);
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      {/* Header */}
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookIcon className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">BiblioTier</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-xs uppercase font-semibold opacity-70">Total Read</span>
            <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => setIsVeoOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Animate Cover (AI)"
            >
              <Video className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsThemeOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Theme Settings"
            >
              <Settings className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-4 py-2 rounded-full text-white font-bold transition-transform hover:scale-105 active:scale-95 shadow-lg"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-5 h-5" />
              <span className="hidden sm:inline">Add Book</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Board */}
      <main className="max-w-7xl mx-auto px-4 py-8 space-y-4">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={(e) => handleDragOver(e, tier.id)}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={(e) => handleDrop(e, tier.id)}
            className={`flex flex-col sm:flex-row min-h-[160px] rounded-xl overflow-hidden shadow-sm border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed ring-4 ring-offset-2' : 'border-transparent'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}11`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : `${currentColors[tier.id]}44`,
              ringColor: `${currentColors[tier.id]}33`
            }}
          >
            {/* Tier Label - 100% Opaque and High Contrast */}
            <div 
              className="sm:w-36 flex flex-col items-center justify-center p-6 text-white font-black text-center shadow-lg z-10"
              style={{ backgroundColor: currentColors[tier.id], opacity: 1 }}
            >
              <span className="text-xl leading-tight uppercase tracking-widest drop-shadow-md">{tier.label}</span>
              <div className="mt-3 px-3 py-1 rounded-full bg-black/30 text-xs font-bold backdrop-blur-sm">
                {booksByTier[tier.id].length}
              </div>
            </div>

            {/* Books Container */}
            <div className="flex-1 p-6 flex flex-wrap gap-6 items-start content-start min-h-[140px]">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  className="relative group w-24 sm:w-32 cursor-grab active:cursor-grabbing transition-transform"
                  onClick={() => setSelectedBook(book)}
                >
                  <img 
                    src={book.coverUrl || 'https://picsum.photos/120/180'} 
                    alt={book.title}
                    className="w-full h-36 sm:h-48 object-cover rounded shadow-lg border-2 border-transparent group-hover:border-white transition-all transform group-hover:scale-105"
                  />
                  <div className="mt-2 text-center">
                    <p className="text-[10px] sm:text-xs font-bold truncate leading-none">{book.title}</p>
                    <p className="text-[9px] sm:text-[10px] opacity-70 truncate mt-1">{book.author}</p>
                  </div>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full h-full flex items-center justify-center opacity-10 italic pointer-events-none text-xl font-bold">
                  Drop Books Here
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {/* Modals */}
      {isSearchOpen && (
        <SearchPanel 
          onClose={() => setIsSearchOpen(false)} 
          onAdd={addBook}
          accentColor={currentColors.accent}
        />
      )}

      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook}
          onDelete={deleteBook}
          accentColor={currentColors.accent}
        />
      )}

      {isThemeOpen && (
        <ThemeManager 
          activeTheme={activeTheme}
          setActiveTheme={setActiveTheme}
          customColors={customColors}
          setCustomColors={setCustomColors}
          onClose={() => setIsThemeOpen(false)}
        />
      )}

      {isVeoOpen && (
        <VeoAnimator 
          onClose={() => setIsVeoOpen(false)}
          accentColor={currentColors.accent}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  Calendar, 
  MessageSquare, 
  Percent, 
  Layout, 
  Plus, 
  History, 
  Book as BookIcon, 
  Volume2, 
  Tablet,
  Check,
  Edit2
} from 'lucide-react';
import { Book, BookFormat, TierId, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingTitle) titleInputRef.current?.focus();
  }, [editingTitle]);

  useEffect(() => {
    if (editingAuthor) authorInputRef.current?.focus();
  }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({
      ...prev,
      sessions: [...prev.sessions, newSession]
    }));
  };

  const removeSession = (id: string) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.filter(s => s.id !== id)
    }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const formatOptions: { value: BookFormat; icon: any }[] = [
    { value: 'Audiobook', icon: Volume2 },
    { value: 'Physical Book', icon: BookIcon },
    { value: 'E-reader', icon: Tablet },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        {/* Header */}
        <div className="p-5 border-b flex items-center justify-between bg-gray-50/50">
          <div className="flex items-center gap-3">
            <span className="px-4 py-1 rounded-full text-xs font-black uppercase text-white shadow-sm" style={{ backgroundColor: accentColor }}>
              {editedBook.tier}
            </span>
            <h2 className="text-sm font-bold uppercase tracking-wider text-gray-400">Book Ledger</h2>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => { if(window.confirm('Permanently remove this book from your collection?')) onDelete(book.id) }}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Delete Book"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-xl transition-all text-gray-400">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 flex flex-col md:row gap-10">
          <div className="flex flex-col md:flex-row gap-10">
            {/* Left Column: Cover & Main Meta */}
            <div className="w-full md:w-80 flex flex-col gap-6">
              <div className="relative group">
                <img 
                  src={book.coverUrl || 'https://picsum.photos/320/480'} 
                  alt={book.title} 
                  className="w-full aspect-[2/3] object-cover rounded-2xl shadow-2xl border-4 border-white"
                />
                <div className="absolute inset-0 rounded-2xl ring-1 ring-black/5 pointer-events-none"></div>
              </div>

              <div className="space-y-4">
                {/* Editable Title */}
                <div className="group relative">
                  {editingTitle ? (
                    <input 
                      ref={titleInputRef}
                      className="w-full text-2xl font-black text-gray-900 leading-tight outline-none border-b-2 border-blue-500 bg-blue-50/50 p-1 rounded"
                      value={editedBook.title}
                      onChange={e => setEditedBook(prev => ({ ...prev, title: e.target.value }))}
                      onBlur={() => setEditingTitle(false)}
                      onKeyDown={e => e.key === 'Enter' && setEditingTitle(false)}
                    />
                  ) : (
                    <div 
                      onClick={() => setEditingTitle(true)}
                      className="cursor-pointer hover:bg-gray-50 p-1 rounded transition-colors group"
                    >
                      <h1 className="text-2xl font-black text-gray-900 leading-tight flex items-center gap-2">
                        {editedBook.title}
                        <Edit2 className="w-4 h-4 text-gray-300 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </h1>
                    </div>
                  )}
                </div>

                {/* Editable Author */}
                <div className="group relative">
                  {editingAuthor ? (
                    <input 
                      ref={authorInputRef}
                      className="w-full text-lg font-medium text-gray-600 outline-none border-b-2 border-blue-400 bg-blue-50/30 p-1 rounded"
                      value={editedBook.author}
                      onChange={e => setEditedBook(prev => ({ ...prev, author: e.target.value }))}
                      onBlur={() => setEditingAuthor(false)}
                      onKeyDown={e => e.key === 'Enter' && setEditingAuthor(false)}
                    />
                  ) : (
                    <div 
                      onClick={() => setEditingAuthor(true)}
                      className="cursor-pointer hover:bg-gray-50 p-1 rounded transition-colors group"
                    >
                      <p className="text-lg font-medium text-gray-600 flex items-center gap-2">
                        {editedBook.author}
                        <Edit2 className="w-4 h-4 text-gray-300 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </p>
                    </div>
                  )}
                </div>
              </div>

              <div className="pt-6 border-t space-y-4">
                <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-400">
                  <Layout className="w-3 h-3" /> Assign Tier
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {TIERS.map(t => (
                    <button
                      key={t.id}
                      onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                      className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                      style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Right Column: History & Notes */}
            <div className="flex-1 space-y-8">
              {/* Reading History */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-gray-500">
                    <History className="w-4 h-4 text-blue-500" /> Reading History
                  </label>
                  <button 
                    onClick={addSession}
                    className="flex items-center gap-1 px-3 py-1.5 rounded-full text-white text-[10px] font-black uppercase transition-transform hover:scale-105 active:scale-95 shadow-md"
                    style={{ backgroundColor: accentColor }}
                  >
                    <Plus className="w-3 h-3" /> Add Session
                  </button>
                </div>

                <div className="space-y-3">
                  {editedBook.sessions.length === 0 ? (
                    <div className="bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl p-8 text-center text-gray-400 italic text-sm">
                      No reading sessions logged yet.
                    </div>
                  ) : (
                    editedBook.sessions.map((session, idx) => (
                      <div key={session.id} className="bg-white border-2 border-gray-100 rounded-2xl p-4 shadow-sm hover:border-gray-200 transition-all space-y-4">
                        <div className="flex flex-wrap items-center gap-4">
                          <div className="flex-1 min-w-[200px] grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                              <span className="text-[10px] font-bold text-gray-400 uppercase">Started</span>
                              <input 
                                type="date" 
                                value={session.startDate}
                                onChange={e => updateSession(session.id, { startDate: e.target.value })}
                                className="w-full p-1.5 rounded-lg border border-gray-100 text-xs focus:ring-1 focus:ring-blue-200 outline-none"
                              />
                            </div>
                            <div className="space-y-1">
                              <span className="text-[10px] font-bold text-gray-400 uppercase">Finished</span>
                              <input 
                                type="date" 
                                value={session.endDate}
                                onChange={e => updateSession(session.id, { endDate: e.target.value })}
                                className="w-full p-1.5 rounded-lg border border-gray-100 text-xs focus:ring-1 focus:ring-blue-200 outline-none"
                              />
                            </div>
                          </div>

                          <div className="flex items-center gap-1.5 bg-gray-50 p-1 rounded-xl border border-gray-100">
                            {formatOptions.map(opt => (
                              <button
                                key={opt.value}
                                onClick={() => updateSession(session.id, { format: opt.value })}
                                title={opt.value}
                                className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-white shadow-sm text-blue-500' : 'text-gray-300 hover:text-gray-400'}`}
                                style={{ color: session.format === opt.value ? accentColor : '' }}
                              >
                                <opt.icon className="w-4 h-4" />
                              </button>
                            ))}
                          </div>

                          <button 
                            onClick={() => removeSession(session.id)}
                            className="p-2 text-gray-300 hover:text-red-400 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>

              {editedBook.tier === 'DNF' && (
                <div className="space-y-4 bg-red-50 p-6 rounded-3xl border-2 border-red-100 shadow-sm">
                  <label className="flex items-center justify-between text-xs font-black uppercase tracking-widest text-red-400">
                    <div className="flex items-center gap-2">
                      <Percent className="w-4 h-4" /> Reading Progress
                    </div>
                    <span className="text-lg">{editedBook.dnfProgress}%</span>
                  </label>
                  <input 
                    type="range" 
                    min="0" 
                    max="100" 
                    value={editedBook.dnfProgress}
                    onChange={e => setEditedBook(prev => ({ ...prev, dnfProgress: parseInt(e.target.value) }))}
                    className="w-full h-2 bg-red-200 rounded-full appearance-none cursor-pointer accent-red-500"
                  />
                  <div className="flex items-center gap-2 text-[10px] font-bold text-red-400/80 italic">
                    <Check className={`w-3 h-3 ${editedBook.dnfProgress > 80 ? 'opacity-100' : 'opacity-20'}`} />
                    {editedBook.dnfProgress > 80 
                      ? "Progress is over 80%. This DNF counts as a 'Read' book." 
                      : "Progress must exceed 80% to count toward your total reads."}
                  </div>
                </div>
              )}

              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-gray-500">
                  <MessageSquare className="w-4 h-4 text-purple-500" /> Notes & Critique
                </label>
                <textarea 
                  value={editedBook.comments}
                  onChange={e => setEditedBook(prev => ({ ...prev, comments: e.target.value }))}
                  placeholder="What made this a God Tier read? Or why did you abandon it?"
                  rows={6}
                  className="w-full p-6 rounded-3xl border-2 border-gray-100 focus:border-blue-300 focus:ring-4 focus:ring-blue-50 outline-none resize-none transition-all shadow-inner text-gray-700 bg-gray-50/30"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t bg-gray-50/80 flex justify-end gap-4">
          <button 
            onClick={onClose}
            className="px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-gray-400 hover:text-gray-600 transition-colors"
          >
            Discard
          </button>
          <button 
            onClick={() => onSave(editedBook)}
            className="px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-white shadow-xl transition-transform hover:scale-105 active:scale-95"
            style={{ backgroundColor: accentColor }}
          >
            Update Ledger
          </button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

import React, { useState } from 'react';
import { Search, X, Loader2, Plus } from 'lucide-react';

interface SearchResult {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
}

interface SearchPanelProps {
  onClose: () => void;
  onAdd: (book: Omit<any, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress'>) => void;
  accentColor: string;
}

const SearchPanel: React.FC<SearchPanelProps> = ({ onClose, onAdd, accentColor }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(`https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(query)}&maxResults=10`);
      const data = await response.json();

      const formatted = (data.items || []).map((item: any) => ({
        id: item.id,
        title: item.volumeInfo.title,
        author: item.volumeInfo.authors?.[0] || 'Unknown Author',
        coverUrl: item.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:') || '',
      }));

      setResults(formatted);
    } catch (error) {
      console.error('Search failed', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-6 border-b flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-black text-gray-800 tracking-tight">Expand Library</h2>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Search Google Books</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
            <X className="w-6 h-6 text-gray-400" />
          </button>
        </div>

        <form onSubmit={handleSearch} className="p-6 bg-gray-50/50">
          <div className="relative">
            <input 
              type="text" 
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by title, author, or ISBN..."
              className="w-full pl-14 pr-4 py-4 rounded-2xl border-2 focus:ring-4 ring-blue-50 outline-none transition-all shadow-inner text-lg font-medium"
              style={{ borderColor: `${accentColor}44` }}
              autoFocus
            />
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-7 h-7 text-gray-300" />
            <button 
              type="submit"
              className="absolute right-3 top-1/2 -translate-y-1/2 px-6 py-2 rounded-xl text-white font-black uppercase text-xs tracking-widest shadow-lg transition-all active:scale-95"
              style={{ backgroundColor: accentColor }}
              disabled={loading}
            >
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Search'}
            </button>
          </div>
        </form>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {results.map(book => (
            <div 
              key={book.id} 
              className="flex items-center gap-5 p-4 rounded-2xl border-2 border-transparent hover:border-gray-100 hover:bg-gray-50 group transition-all"
            >
              <div className="relative">
                <img 
                  src={book.coverUrl || 'https://picsum.photos/60/90'} 
                  alt={book.title} 
                  className="w-20 h-28 object-cover rounded-xl shadow-md border-2 border-white"
                />
                <div className="absolute inset-0 rounded-xl ring-1 ring-black/5 pointer-events-none"></div>
              </div>
              <div className="flex-1">
                <h3 className="font-black text-gray-900 leading-tight text-lg">{book.title}</h3>
                <p className="text-sm font-medium text-gray-500 mt-1">{book.author}</p>
              </div>
              <button 
                onClick={() => onAdd(book)}
                className="p-4 rounded-2xl text-white shadow-xl transform hover:scale-110 active:scale-90 transition-all"
                style={{ backgroundColor: accentColor }}
              >
                <Plus className="w-7 h-7" />
              </button>
            </div>
          ))}
          {!loading && results.length === 0 && query && (
            <div className="text-center py-16">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <Search className="w-10 h-10 text-gray-300" />
              </div>
              <p className="text-gray-400 font-bold">No results found for "{query}"</p>
            </div>
          )}
          {!query && (
            <div className="text-center py-16 opacity-30">
              <Search className="w-16 h-16 mx-auto mb-4" />
              <p className="font-black text-xl uppercase tracking-tighter italic">Enter a keyword to begin</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SearchPanel;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Book as BookIcon, 
  Settings, 
  Plus, 
  Video,
  Volume2
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors, ReadingSession } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence & Migration
  useEffect(() => {
    const savedBooks = localStorage.getItem('biblio_books');
    const savedTheme = localStorage.getItem('biblio_theme');
    const savedColors = localStorage.getItem('biblio_colors');

    if (savedBooks) {
      const parsed: any[] = JSON.parse(savedBooks);
      const migrated = parsed.map(b => {
        if (!b.sessions) {
          return {
            ...b,
            sessions: b.dateStarted || b.dateFinished ? [{
              id: Math.random().toString(36).substr(2, 9),
              startDate: b.dateStarted || '',
              endDate: b.dateFinished || '',
              format: b.format || 'Physical Book'
            }] : []
          };
        }
        return b;
      });
      setBooks(migrated);
    }
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
  }, []);

  useEffect(() => {
    localStorage.setItem('biblio_books', JSON.stringify(books));
    localStorage.setItem('biblio_theme', activeTheme);
    localStorage.setItem('biblio_colors', JSON.stringify(customColors));
  }, [books, activeTheme, customColors]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  const addBook = useCallback((newBook: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress'>) => {
    const book: Book = {
      ...newBook,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
    };
    setBooks(prev => [...prev, book]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      if (book.tier === 'DNF' && book.dnfProgress > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  // Enhanced move logic for reordering
  const moveAndReorderBook = (draggedId: string, targetTier: TierId, targetBookId: string | null = null) => {
    setBooks(prev => {
      const newBooks = [...prev];
      const draggedIndex = newBooks.findIndex(b => b.id === draggedId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = newBooks.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = newBooks.findIndex(b => b.id === targetBookId);
        newBooks.splice(targetIndex, 0, draggedBook);
      } else {
        // Find last index of that tier and push after it
        const lastInTierIndex = [...newBooks].reverse().findIndex(b => b.tier === targetTier);
        if (lastInTierIndex === -1) {
          newBooks.push(draggedBook);
        } else {
          const actualIndex = newBooks.length - lastInTierIndex;
          newBooks.splice(actualIndex, 0, draggedBook);
        }
      }
      return newBooks;
    });
  };

  // Drag and Drop Handlers
  const handleDragStart = (id: string) => {
    setDraggedBookId(id);
  };

  const handleDragOverTier = (e: React.DragEvent, tierId: TierId) => {
    e.preventDefault();
    setDragOverTier(tierId);
  };

  const handleDragOverBook = (e: React.DragEvent, bookId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDragOverBookId(bookId);
  };

  const handleDropOnTier = (e: React.DragEvent, tierId: TierId) => {
    e.preventDefault();
    if (draggedBookId) {
      moveAndReorderBook(draggedBookId, tierId, null);
    }
    resetDragState();
  };

  const handleDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDragState();
  };

  const resetDragState = () => {
    setDraggedBookId(null);
    setDragOverTier(null);
    setDragOverBookId(null);
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      {/* Header */}
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookIcon className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">BiblioTier</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-xs uppercase font-semibold opacity-70">Total Read</span>
            <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => setIsVeoOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Animate Cover (AI)"
            >
              <Video className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsThemeOpen(true)}
              className="p-2 rounded-full transition-transform hover:scale-110 active:scale-95 border"
              style={{ borderColor: currentColors.accent, color: currentColors.accent }}
              title="Theme Settings"
            >
              <Settings className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-4 py-2 rounded-full text-white font-bold transition-transform hover:scale-105 active:scale-95 shadow-lg"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-5 h-5" />
              <span className="hidden sm:inline">Add Book</span>
            </button>
          </div>
        </div>
      </header>

      {/* Main Board */}
      <main className="max-w-7xl mx-auto px-4 py-8 space-y-4">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={(e) => handleDragOverTier(e, tier.id)}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={(e) => handleDropOnTier(e, tier.id)}
            className={`flex flex-col sm:flex-row min-h-[160px] rounded-xl overflow-hidden shadow-sm border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed ring-4 ring-offset-2' : 'border-transparent'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}11`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : `${currentColors[tier.id]}44`,
              ringColor: `${currentColors[tier.id]}33`
            }}
          >
            {/* Tier Label - 100% Opaque and High Contrast */}
            <div 
              className="sm:w-36 flex flex-col items-center justify-center p-6 text-white font-black text-center shadow-lg z-10"
              style={{ backgroundColor: currentColors[tier.id], opacity: 1 }}
            >
              <span className="text-xl leading-tight uppercase tracking-widest drop-shadow-md">{tier.label}</span>
              <div className="mt-3 px-3 py-1 rounded-full bg-black/30 text-xs font-bold backdrop-blur-sm">
                {booksByTier[tier.id].length}
              </div>
            </div>

            {/* Books Container */}
            <div className="flex-1 p-6 flex flex-wrap gap-6 items-start content-start min-h-[140px]">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  onDragOver={(e) => handleDragOverBook(e, book.id)}
                  onDragLeave={() => setDragOverBookId(null)}
                  onDrop={(e) => handleDropOnBook(e, book.id, tier.id)}
                  className={`relative group w-24 sm:w-32 cursor-grab active:cursor-grabbing transition-all ${draggedBookId === book.id ? 'opacity-40 grayscale rotate-2 scale-90' : ''} ${dragOverBookId === book.id ? 'border-l-4 border-white' : ''}`}
                  style={{ borderLeftColor: dragOverBookId === book.id ? currentColors.accent : 'transparent' }}
                  onClick={() => setSelectedBook(book)}
                >
                  <img 
                    src={book.coverUrl || 'https://picsum.photos/120/180'} 
                    alt={book.title}
                    className="w-full h-36 sm:h-48 object-cover rounded shadow-lg border-2 border-transparent group-hover:border-white transition-all transform group-hover:scale-105"
                  />
                  <div className="mt-2 text-center">
                    <p className="text-[10px] sm:text-xs font-bold truncate leading-none">{book.title}</p>
                    <p className="text-[9px] sm:text-[10px] opacity-70 truncate mt-1">{book.author}</p>
                  </div>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full h-full flex items-center justify-center opacity-10 italic pointer-events-none text-xl font-bold">
                  Drop Books Here
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {/* Modals */}
      {isSearchOpen && (
        <SearchPanel 
          onClose={() => setIsSearchOpen(false)} 
          onAdd={addBook}
          accentColor={currentColors.accent}
        />
      )}

      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook}
          onDelete={deleteBook}
          accentColor={currentColors.accent}
        />
      )}

      {isThemeOpen && (
        <ThemeManager 
          activeTheme={activeTheme}
          setActiveTheme={setActiveTheme}
          customColors={customColors}
          setCustomColors={setCustomColors}
          onClose={() => setIsThemeOpen(false)}
        />
      )}

      {isVeoOpen && (
        <VeoAnimator 
          onClose={() => setIsVeoOpen(false)}
          accentColor={currentColors.accent}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  Calendar, 
  MessageSquare, 
  Percent, 
  Layout, 
  Plus, 
  History, 
  Book as BookIcon, 
  Headphones, 
  Tablet,
  Check,
  Edit2
} from 'lucide-react';
import { Book, BookFormat, TierId, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingTitle) titleInputRef.current?.focus();
  }, [editingTitle]);

  useEffect(() => {
    if (editingAuthor) authorInputRef.current?.focus();
  }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({
      ...prev,
      sessions: [...prev.sessions, newSession]
    }));
  };

  const removeSession = (id: string) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.filter(s => s.id !== id)
    }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const formatOptions: { value: BookFormat; icon: any; label: string }[] = [
    { value: 'Audiobook', icon: Headphones, label: 'Audiobook' },
    { value: 'Physical Book', icon: BookIcon, label: 'Physical Book' },
    { value: 'E-reader', icon: Tablet, label: 'E-reader' },
