// --- Types ---
type TierId = 'TBR' | 'GOD' | 'A' | 'B' | 'C' | 'DNF';
type BookFormat = 'Audiobook' | 'Physical Book' | 'E-reader';

interface ReadingSession {
  id: string;
  startDate: string;
  endDate: string;
  format: BookFormat;
}

interface Book {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
  tier: TierId;
  sessions: ReadingSession[];
  comments: string;
  dnfProgress: number;
}

interface UserConfig {
  goal2026: number;
  theme: string;
