import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  Book as BookIcon, 
  Plus, 
  Video,
  Search, 
  X, 
  Loader2,
  Trash2, 
  Download,
  Upload,
  Settings,
  Calendar, 
  MessageSquare, 
  Layout, 
  History, 
  Trophy,
  Target,
