                  placeholder="Enter Title"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400">Author</label>
                <input 
                  value={edited.author} 
                  onChange={e => setEdited(p => ({ ...p, author: e.target.value }))} 
