import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(<App />);
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Book as BookIcon, 
  Settings, 
  Plus, 
  Video,
  ChevronRight
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [goal, setGoal] = useState<number>(12);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence & Migration
  useEffect(() => {
    const savedBooks = localStorage.getItem('shelfie_books');
    const savedTheme = localStorage.getItem('shelfie_theme');
    const savedColors = localStorage.getItem('shelfie_colors');
    const savedGoal = localStorage.getItem('shelfie_goal');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
    if (savedGoal) setGoal(parseInt(savedGoal));
  }, []);

  useEffect(() => {
    localStorage.setItem('shelfie_books', JSON.stringify(books));
    localStorage.setItem('shelfie_theme', activeTheme);
    localStorage.setItem('shelfie_colors', JSON.stringify(customColors));
    localStorage.setItem('shelfie_goal', goal.toString());
  }, [books, activeTheme, customColors, goal]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  const addBook = useCallback((newBook: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress'>) => {
    const book: Book = {
      ...newBook,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
    };
    setBooks(prev => [...prev, book]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      // Standard Tiers count as read
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      // DNF counts if progress is > 80%
      if (book.tier === 'DNF' && (book.dnfProgress || 0) > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    // We maintain the order from the main books array
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveAndReorderBook = (dragId: string, targetTier: TierId, targetBookId: string | null) => {
    setBooks(prev => {
      const result = [...prev];
      const draggedIndex = result.findIndex(b => b.id === dragId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = result.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = result.findIndex(b => b.id === targetBookId);
        result.splice(targetIndex, 0, draggedBook);
      } else {
        result.push(draggedBook);
      }
      return result;
    });
  };

  const handleDragStart = (id: string) => setDraggedBookId(id);
  const resetDrag = () => { setDraggedBookId(null); setDragOverTier(null); setDragOverBookId(null); };

  const onDropOnTier = (tierId: TierId) => {
    if (draggedBookId) moveAndReorderBook(draggedBookId, tierId, null);
    resetDrag();
  };

  const onDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDrag();
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookIcon className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">Shelfie</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-[10px] uppercase font-black opacity-40 tracking-widest">
              {goal > 0 ? 'Yearly Progress' : 'Books Read'}
            </span>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
              {goal > 0 && <span className="text-sm font-bold opacity-30">/ {goal}</span>}
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => setIsVeoOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }}><Video className="w-5 h-5" /></button>
            <button onClick={() => setIsThemeOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }}><Settings className="w-5 h-5" /></button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-5 py-2 rounded-full text-white font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-4 h-4" /> Add Book
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-10 space-y-6">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={e => { e.preventDefault(); setDragOverTier(tier.id); }}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={() => onDropOnTier(tier.id)}
            className={`flex flex-col md:flex-row min-h-[180px] rounded-3xl overflow-hidden border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed shadow-xl' : 'border-transparent shadow-sm'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}10`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : 'transparent'
            }}
          >
            <div 
              className="md:w-36 p-6 flex flex-col items-center justify-center text-white font-black text-center"
              style={{ backgroundColor: currentColors[tier.id] }}
            >
              <span className="uppercase tracking-widest text-sm drop-shadow-sm">{tier.label}</span>
              <div className="mt-2 text-xs opacity-60 font-bold">{booksByTier[tier.id].length} Books</div>
            </div>

            <div className="flex-1 p-6 flex flex-wrap gap-6 min-h-[140px] items-start">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  onDragOver={e => { e.preventDefault(); e.stopPropagation(); setDragOverBookId(book.id); }}
                  onDragLeave={() => setDragOverBookId(null)}
                  onDrop={e => onDropOnBook(e, book.id, tier.id)}
                  onClick={() => setSelectedBook(book)}
                  className={`group w-24 sm:w-32 cursor-pointer transition-all ${draggedBookId === book.id ? 'opacity-20 scale-90' : 'hover:-translate-y-2'} ${dragOverBookId === book.id ? 'ring-4 ring-offset-4 ring-white' : ''}`}
                  style={{ ['--tw-ring-color' as any]: currentColors.accent }}
                >
                  <div className="relative aspect-[2/3] rounded-xl overflow-hidden shadow-lg mb-2">
                    <img src={book.coverUrl || 'https://picsum.photos/120/180'} className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-2">
                      <ChevronRight className="w-5 h-5 text-white ml-auto" />
                    </div>
                  </div>
                  <h3 className="font-bold text-[10px] leading-tight truncate px-1">{book.title}</h3>
                  <p className="text-[9px] opacity-50 truncate px-1">{book.author}</p>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full flex items-center justify-center py-10 opacity-10 font-black text-2xl uppercase italic tracking-tighter">Empty Shelf</div>
              )}
            </div>
          </div>
        ))}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBook} accentColor={currentColors.accent} />}
      {isThemeOpen && <ThemeManager activeTheme={activeTheme} setActiveTheme={setActiveTheme} customColors={customColors} setCustomColors={setCustomColors} goal={goal} setGoal={setGoal} onClose={() => setIsThemeOpen(false)} />}
      {isVeoOpen && <VeoAnimator onClose={() => setIsVeoOpen(false)} accentColor={currentColors.accent} />}
      {selectedBook && <BookModal book={selectedBook} onClose={() => setSelectedBook(null)} onSave={updateBook} onDelete={deleteBook} accentColor={currentColors.accent} />}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  MessageSquare, 
  Percent, 
  Layout, 
  Plus, 
  History, 
  Book as BookIcon, 
  Headphones, 
  Tablet,
  Check,
  Edit2
} from 'lucide-react';
import { Book, BookFormat, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { if (editingTitle) titleInputRef.current?.focus(); }, [editingTitle]);
  useEffect(() => { if (editingAuthor) authorInputRef.current?.focus(); }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({ ...prev, sessions: [...prev.sessions, newSession] }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const formatOptions: { value: BookFormat; icon: any }[] = [
    { value: 'Audiobook', icon: Headphones },
    { value: 'Physical Book', icon: BookIcon },
    { value: 'E-reader', icon: Tablet },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b flex items-center justify-between bg-gray-50/50">
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 italic">2026 Archive Detail</span>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => { if(window.confirm('Delete this book?')) onDelete(book.id) }} 
              className="p-2 text-gray-300 hover:text-red-500 transition-colors"
            ><Trash2 className="w-5 h-5" /></button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-all"><X className="w-6 h-6" /></button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 flex flex-col md:flex-row gap-12">
          <div className="w-full md:w-80 flex flex-col gap-6">
            <img src={book.coverUrl || 'https://picsum.photos/320/480'} className="w-full aspect-[2/3] object-cover rounded-3xl shadow-2xl ring-8 ring-gray-50" />

            <div className="space-y-4">
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Title</label>
                {editingTitle ? (
                  <input ref={titleInputRef} className="w-full text-lg font-black bg-transparent outline-none" value={editedBook.title} onChange={e => setEditedBook(p => ({ ...p, title: e.target.value }))} onBlur={() => setEditingTitle(false)} />
                ) : (
                  <div onClick={() => setEditingTitle(true)} className="flex items-center gap-2 cursor-pointer font-black text-lg">{editedBook.title} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Author</label>
                {editingAuthor ? (
                  <input ref={authorInputRef} className="w-full text-sm font-bold bg-transparent outline-none" value={editedBook.author} onChange={e => setEditedBook(p => ({ ...p, author: e.target.value }))} onBlur={() => setEditingAuthor(false)} />
                ) : (
                  <div onClick={() => setEditingAuthor(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500">{editedBook.author} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
            </div>

            <div className="pt-6 border-t grid grid-cols-2 gap-2">
              {TIERS.map(t => (
                <button
                  key={t.id}
                  onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                  className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent shadow-lg' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                  style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                >{t.label}</button>
              ))}
            </div>
          </div>

          <div className="flex-1 space-y-8">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><History className="w-4 h-4" /> Reading Sessions</h3>
                <button onClick={addSession} className="px-4 py-2 rounded-full text-[10px] font-black uppercase text-white shadow-lg transition-transform active:scale-95" style={{ backgroundColor: accentColor }}>+ Session</button>
              </div>

              <div className="space-y-3">
                {editedBook.sessions.map(session => (
                  <div key={session.id} className="bg-gray-50/50 border-2 border-gray-100 rounded-2xl p-4 flex flex-wrap items-center gap-4">
                    <div className="flex gap-2 bg-white p-1 rounded-xl border">
                      {formatOptions.map(opt => (
                        <button key={opt.value} onClick={() => updateSession(session.id, { format: opt.value })} className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-indigo-600 text-white' : 'text-gray-300'}`} style={{ backgroundColor: session.format === opt.value ? accentColor : '' }}><opt.icon className="w-4 h-4" /></button>
                      ))}
                    </div>
                    <div className="flex gap-2 flex-1 min-w-[150px]">
                      <input type="date" value={session.startDate} onChange={e => updateSession(session.id, { startDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border flex-1" />
                      <input type="date" value={session.endDate} onChange={e => updateSession(session.id, { endDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border flex-1" />
                    </div>
                    <button onClick={() => setEditedBook(p => ({ ...p, sessions: p.sessions.filter(s => s.id !== session.id) }))} className="text-gray-300 hover:text-red-400"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="p-6 bg-red-50 rounded-3xl border-2 border-red-100 space-y-4 animate-in slide-in-from-top-2">
                <div className="flex justify-between items-center text-xs font-black uppercase tracking-widest text-red-500">
                  <div className="flex items-center gap-2"><Percent className="w-4 h-4" /> Progress Read</div>
                  <span className="text-lg">{editedBook.dnfProgress || 0}%</span>
                </div>
                <input type="range" min="0" max="100" value={editedBook.dnfProgress || 0} onChange={e => setEditedBook(p => ({ ...p, dnfProgress: parseInt(e.target.value) }))} className="w-full h-3 bg-red-200 rounded-full appearance-none accent-red-600 cursor-pointer" />
                <div className="text-[10px] font-bold text-red-400 flex items-center gap-2">
                  <Check className={`w-3 h-3 transition-opacity ${editedBook.dnfProgress > 80 ? 'opacity-100' : 'opacity-20'}`} />
                  {editedBook.dnfProgress > 80 ? "Above 80% - Counts towards total read books!" : "Below 80% - Not counted in yearly progress."}
                </div>
              </div>
            )}

            <div className="space-y-3">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><MessageSquare className="w-4 h-4" /> Reflections</label>
              <textarea value={editedBook.comments} onChange={e => setEditedBook(p => ({ ...p, comments: e.target.value }))} className="w-full p-6 rounded-[32px] border-2 border-gray-100 focus:border-indigo-100 outline-none h-40 resize-none bg-gray-50/50 transition-all" placeholder="Notes about this book..." />
            </div>
          </div>
        </div>

        <div className="p-8 border-t bg-gray-50/80 flex justify-end gap-4">
          <button onClick={onClose} className="font-bold text-gray-400 uppercase text-xs tracking-widest">Cancel</button>
          <button onClick={() => onSave(editedBook)} className="px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-white shadow-xl hover:scale-105 active:scale-95 transition-all" style={{ backgroundColor: accentColor }}>Update Log</button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

