export type ThemePreset = 'Dark Academia' | 'Cyberpunk' | 'Pastel Dream' | 'Custom';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  BookOpen, 
  Settings, 
  Plus, 
  Video,
  ChevronRight
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [goal, setGoal] = useState<number>(12);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const savedBooks = localStorage.getItem('shelfie_books');
    const savedTheme = localStorage.getItem('shelfie_theme');
    const savedColors = localStorage.getItem('shelfie_colors');
    const savedGoal = localStorage.getItem('shelfie_goal');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
    if (savedGoal) setGoal(parseInt(savedGoal));
  }, []);

  useEffect(() => {
    localStorage.setItem('shelfie_books', JSON.stringify(books));
    localStorage.setItem('shelfie_theme', activeTheme);
    localStorage.setItem('shelfie_colors', JSON.stringify(customColors));
    localStorage.setItem('shelfie_goal', goal.toString());
  }, [books, activeTheme, customColors, goal]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  const addBooks = useCallback((newBooks: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => {
    const preparedBooks: Book[] = newBooks.map(nb => ({
      ...nb,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
      tags: [],
    }));
    setBooks(prev => [...prev, ...preparedBooks]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      // Standard completed tiers
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      // DNF counts only if > 80% progress
      if (book.tier === 'DNF' && (book.dnfProgress || 0) > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveAndReorderBook = (dragId: string, targetTier: TierId, targetBookId: string | null) => {
    setBooks(prev => {
      const result = [...prev];
      const draggedIndex = result.findIndex(b => b.id === dragId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = result.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = result.findIndex(b => b.id === targetBookId);
        result.splice(targetIndex, 0, draggedBook);
      } else {
        result.push(draggedBook);
      }
      return result;
    });
  };

  const handleDragStart = (id: string) => setDraggedBookId(id);
  const resetDrag = () => { setDraggedBookId(null); setDragOverTier(null); setDragOverBookId(null); };

  const onDropOnTier = (tierId: TierId) => {
    if (draggedBookId) moveAndReorderBook(draggedBookId, tierId, null);
    resetDrag();
  };

  const onDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDrag();
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookOpen className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">Shelfie</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-[10px] uppercase font-black opacity-40 tracking-widest">
              {goal > 0 ? 'Yearly Progress' : 'Total Read'}
            </span>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
              {goal > 0 && <span className="text-sm font-bold opacity-30">/ {goal}</span>}
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => setIsVeoOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Animate Cover"><Video className="w-5 h-5" /></button>
            <button onClick={() => setIsThemeOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Settings"><Settings className="w-5 h-5" /></button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-5 py-2 rounded-full text-white font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-4 h-4" /> Add Book
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-10 space-y-6">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={e => { e.preventDefault(); setDragOverTier(tier.id); }}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={() => onDropOnTier(tier.id)}
            className={`flex flex-col md:flex-row min-h-[180px] rounded-3xl overflow-hidden border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed shadow-xl bg-black/5' : 'border-transparent shadow-sm'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}10`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : 'transparent'
            }}
          >
            <div 
              className="md:w-36 p-6 flex flex-col items-center justify-center text-white font-black text-center"
              style={{ backgroundColor: currentColors[tier.id] }}
            >
              <span className="uppercase tracking-widest text-sm drop-shadow-sm">{tier.label}</span>
              <div className="mt-2 text-xs opacity-60 font-bold">{booksByTier[tier.id].length} Books</div>
            </div>

            <div className="flex-1 p-6 flex flex-wrap gap-6 min-h-[140px] items-start">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  onDragOver={e => { e.preventDefault(); e.stopPropagation(); setDragOverBookId(book.id); }}
                  onDragLeave={() => setDragOverBookId(null)}
                  onDrop={e => onDropOnBook(e, book.id, tier.id)}
                  onClick={() => setSelectedBook(book)}
                  className={`group w-24 sm:w-32 cursor-pointer transition-all ${draggedBookId === book.id ? 'opacity-20 scale-90 grayscale' : 'hover:-translate-y-2'} ${dragOverBookId === book.id ? 'ring-4 ring-offset-4 ring-white' : ''}`}
                  style={{ ['--tw-ring-color' as any]: currentColors.accent }}
                >
                  <div className="relative aspect-[2/3] rounded-xl overflow-hidden shadow-lg mb-2 bg-gray-200">
                    <img src={book.coverUrl || 'https://picsum.photos/120/180'} className="w-full h-full object-cover" alt={book.title} />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-2">
                      <ChevronRight className="w-5 h-5 text-white ml-auto" />
                    </div>
                  </div>
                  <h3 className="font-bold text-[10px] leading-tight truncate px-1">{book.title}</h3>
                  <p className="text-[9px] opacity-50 truncate px-1">{book.author}</p>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full flex items-center justify-center py-10 opacity-10 font-black text-2xl uppercase italic tracking-tighter flex-col gap-2">
                  <BookOpen className="w-12 h-12" />
                  <span>Empty Shelf</span>
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBooks} accentColor={currentColors.accent} />}
      {isThemeOpen && <ThemeManager activeTheme={activeTheme} setActiveTheme={setActiveTheme} customColors={customColors} setCustomColors={setCustomColors} goal={goal} setGoal={setGoal} onClose={() => setIsThemeOpen(false)} />}
      {isVeoOpen && <VeoAnimator onClose={() => setIsVeoOpen(false)} accentColor={currentColors.accent} />}
      {selectedBook && <BookModal book={selectedBook} onClose={() => setSelectedBook(null)} onSave={updateBook} onDelete={deleteBook} accentColor={currentColors.accent} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, X, Loader2, Plus, BookOpen, Check } from 'lucide-react';

interface SearchResult {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
}

interface SearchPanelProps {
  onClose: () => void;
  onAdd: (books: Omit<any, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => void;
  accentColor: string;
}

const SearchPanel: React.FC<SearchPanelProps> = ({ onClose, onAdd, accentColor }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(`https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(query)}&maxResults=10`);
      const data = await response.json();

      const formatted = (data.items || []).map((item: any) => ({
        id: item.id,
        title: item.volumeInfo.title,
        author: item.volumeInfo.authors?.[0] || 'Unknown Author',
        coverUrl: item.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:') || '',
      }));

      setResults(formatted);
      setSelectedIds(new Set());
    } catch (error) {
      console.error('Search failed', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleAddSelected = () => {
    const selectedBooks = results.filter(r => selectedIds.has(r.id));
    if (selectedBooks.length === 0) return;
    onAdd(selectedBooks);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-6 border-b flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-black text-gray-800 tracking-tight">Expand Library</h2>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Search Google Books</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
            <X className="w-6 h-6 text-gray-400" />
          </button>
        </div>

        <form onSubmit={handleSearch} className="p-6 bg-gray-50/50">
          <div className="relative">
            <input 
              type="text" 
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by title, author, or ISBN..."
              className="w-full pl-14 pr-4 py-4 rounded-2xl border-2 focus:ring-4 ring-blue-50 outline-none transition-all shadow-inner text-lg font-medium"
              style={{ borderColor: `${accentColor}44` }}
              autoFocus
            />
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-7 h-7 text-gray-300" />
            <button 
              type="submit"
              className="absolute right-3 top-1/2 -translate-y-1/2 px-6 py-2 rounded-xl text-white font-black uppercase text-xs tracking-widest shadow-lg transition-all active:scale-95"
              style={{ backgroundColor: accentColor }}
              disabled={loading}
            >
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Search'}
            </button>
          </div>
        </form>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {results.map(book => {
            const isSelected = selectedIds.has(book.id);
            return (
              <div 
                key={book.id} 
                onClick={() => toggleSelection(book.id)}
                className={`flex items-center gap-5 p-4 rounded-2xl border-2 cursor-pointer transition-all ${isSelected ? 'bg-indigo-50 border-indigo-200' : 'border-transparent hover:border-gray-100 hover:bg-gray-50'}`}
              >
                <div className="relative">
                  {book.coverUrl ? (
                    <img 
                      src={book.coverUrl} 
                      alt={book.title} 
                      className="w-20 h-28 object-cover rounded-xl shadow-md border-2 border-white"
                    />
                  ) : (
                    <div className="w-20 h-28 bg-gray-100 rounded-xl flex items-center justify-center border-2 border-white">
                      <BookOpen className="w-8 h-8 text-gray-300" />
                    </div>
                  )}
                  {isSelected && (
                    <div className="absolute top-1 right-1 bg-white rounded-full p-1 shadow-md border" style={{ color: accentColor }}>
                      <Check className="w-4 h-4" strokeWidth={3} />
                    </div>
                  )}
                </div>
                <div className="flex-1">
                  <h3 className="font-black text-gray-900 leading-tight text-lg">{book.title}</h3>
                  <p className="text-sm font-medium text-gray-500 mt-1">{book.author}</p>
                </div>
              </div>
            );
          })}
          {!loading && results.length === 0 && query && (
            <div className="text-center py-16">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <Search className="w-10 h-10 text-gray-300" />
              </div>
              <p className="text-gray-400 font-bold">No results found for "{query}"</p>
            </div>
          )}
          {!query && (
            <div className="text-center py-16 opacity-30">
              <BookOpen className="w-16 h-16 mx-auto mb-4" />
              <p className="font-black text-xl uppercase tracking-tighter italic">Enter a keyword to begin</p>
            </div>
          )}
        </div>

        {selectedIds.size > 0 && (
          <div className="p-6 border-t bg-gray-50 flex items-center justify-between">
            <span className="font-bold text-gray-500 text-sm">{selectedIds.size} books selected</span>
            <button 
              onClick={handleAddSelected}
              className="px-8 py-3 rounded-2xl text-white font-black uppercase text-xs tracking-widest shadow-xl transform transition-all active:scale-95"
              style={{ backgroundColor: accentColor }}
            >
              Add to Library
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchPanel;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  MessageSquare, 
  Percent, 
  Layout, 
  Plus, 
  History, 
  BookOpen, 
  Headphones, 
  Tablet,
  Check,
  Edit2,
  Tag as TagIcon
} from 'lucide-react';
import { Book, BookFormat, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book, tags: book.tags || [] });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);
  const [tagInput, setTagInput] = useState('');

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { if (editingTitle) titleInputRef.current?.focus(); }, [editingTitle]);
  useEffect(() => { if (editingAuthor) authorInputRef.current?.focus(); }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({ ...prev, sessions: [...prev.sessions, newSession] }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const addTag = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      e.preventDefault();
      if (!editedBook.tags.includes(tagInput.trim())) {
        setEditedBook(prev => ({ ...prev, tags: [...prev.tags, tagInput.trim()] }));
      }
      setTagInput('');
    }
  };

  const removeTag = (tag: string) => {
    setEditedBook(prev => ({ ...prev, tags: prev.tags.filter(t => t !== tag) }));
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm(`Permanently remove "${editedBook.title}" from your collection? This cannot be undone.`)) {
      onDelete(editedBook.id);
    }
  };

  const formatOptions: { value: BookFormat; icon: any; title: string }[] = [
    { value: 'Audiobook', icon: Headphones, title: 'Listen to as Audiobook' },
    { value: 'Physical Book', icon: BookOpen, title: 'Read Physical Copy' },
    { value: 'E-reader', icon: Tablet, title: 'Read on E-reader' },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b flex items-center justify-between bg-gray-50/50">
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 italic">Reading Archive Detail</span>
          <div className="flex items-center gap-3">
            <button 
              onClick={handleDelete}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Delete Book"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-all">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 flex flex-col md:flex-row gap-12">
          <div className="w-full md:w-80 flex flex-col gap-6">
            <div className="relative group">
              <img src={book.coverUrl || 'https://picsum.photos/320/480'} className="w-full aspect-[2/3] object-cover rounded-3xl shadow-2xl ring-8 ring-gray-50 bg-gray-100" alt={book.title} />
              <div className="absolute inset-0 rounded-3xl ring-1 ring-black/10 pointer-events-none"></div>
            </div>

            <div className="space-y-4">
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Title</label>
                {editingTitle ? (
                  <input ref={titleInputRef} className="w-full text-lg font-black bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.title} onChange={e => setEditedBook(p => ({ ...p, title: e.target.value }))} onBlur={() => setEditingTitle(false)} onKeyDown={e => e.key === 'Enter' && setEditingTitle(false)} />
                ) : (
                  <div onClick={() => setEditingTitle(true)} className="flex items-center gap-2 cursor-pointer font-black text-lg group-hover:text-indigo-600 transition-colors">{editedBook.title} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Author</label>
                {editingAuthor ? (
                  <input ref={authorInputRef} className="w-full text-sm font-bold bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.author} onChange={e => setEditedBook(p => ({ ...p, author: e.target.value }))} onBlur={() => setEditingAuthor(false)} onKeyDown={e => e.key === 'Enter' && setEditingAuthor(false)} />
                ) : (
                  <div onClick={() => setEditingAuthor(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500 group-hover:text-indigo-600 transition-colors">{editedBook.author} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
            </div>

            <div className="pt-6 border-t grid grid-cols-2 gap-2">
              {TIERS.map(t => (
                <button
                  key={t.id}
                  onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                  className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent shadow-lg' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                  style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                >{t.label}</button>
              ))}
            </div>
          </div>

          <div className="flex-1 space-y-8">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><History className="w-4 h-4" /> Reading Sessions</h3>
                <button onClick={addSession} className="px-4 py-2 rounded-full text-[10px] font-black uppercase text-white shadow-lg transition-transform hover:scale-105 active:scale-95" style={{ backgroundColor: accentColor }}>+ Session</button>
              </div>

              <div className="space-y-3">
                {editedBook.sessions.map(session => (
                  <div key={session.id} className="bg-gray-50/50 border-2 border-gray-100 rounded-2xl p-4 flex flex-wrap items-center gap-4 hover:border-indigo-100 transition-colors">
                    <div className="flex gap-2 bg-white p-1 rounded-xl border border-gray-100">
                      {formatOptions.map(opt => (
                        <button 
                          key={opt.value} 
                          onClick={() => updateSession(session.id, { format: opt.value })} 
                          className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-300 hover:text-gray-400'}`} 
                          style={{ backgroundColor: session.format === opt.value ? accentColor : '' }}
                          title={opt.title}
                        >
                          <opt.icon className="w-4 h-4" />
                        </button>
                      ))}
                    </div>
                    <div className="flex gap-2 flex-1 min-w-[150px]">
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">Start</span>
                        <input type="date" value={session.startDate} onChange={e => updateSession(session.id, { startDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">End</span>
                        <input type="date" value={session.endDate} onChange={e => updateSession(session.id, { endDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                    </div>
                    <button onClick={() => setEditedBook(p => ({ ...p, sessions: p.sessions.filter(s => s.id !== session.id) }))} className="text-gray-300 hover:text-red-400 transition-colors p-2"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="p-6 bg-red-50 rounded-3xl border-2 border-red-100 space-y-4 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center text-xs font-black uppercase tracking-widest text-red-500">
                  <div className="flex items-center gap-2"><Percent className="w-4 h-4" /> DNF Progress</div>
                  <span className="text-lg">{editedBook.dnfProgress || 0}%</span>
                </div>
                <input type="range" min="0" max="100" value={editedBook.dnfProgress || 0} onChange={e => setEditedBook(p => ({ ...p, dnfProgress: parseInt(e.target.value) }))} className="w-full h-3 bg-red-200 rounded-full appearance-none accent-red-600 cursor-pointer" />
                <div className="text-[10px] font-bold text-red-400 flex items-center gap-2">
                  <Check className={`w-3 h-3 transition-opacity ${editedBook.dnfProgress > 80 ? 'opacity-100' : 'opacity-20'}`} />
                  {editedBook.dnfProgress > 80 ? "Reached 80% - This book now counts towards your total read count!" : "Below 80% - Not counted in your yearly progress statistics."}
                </div>
              </div>
            )}

            <div className="space-y-4">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><TagIcon className="w-4 h-4" /> Categorization (Tags)</label>
              <div className="flex flex-wrap gap-2 mb-2">
                {editedBook.tags.map(tag => (
                  <span key={tag} className="flex items-center gap-1 px-3 py-1 rounded-full bg-indigo-50 text-indigo-700 text-[10px] font-black uppercase border border-indigo-100">
                    {tag}
                    <button onClick={() => removeTag(tag)} className="hover:text-red-500"><X className="w-3 h-3" /></button>
                  </span>
                ))}
                <input 
                  type="text"
                  value={tagInput}
                  onChange={e => setTagInput(e.target.value)}
                  onKeyDown={addTag}
                  placeholder="Type tag & press Enter (e.g. 2026, Sci-Fi)"
                  className="bg-transparent border-b-2 border-gray-100 text-[10px] outline-none focus:border-indigo-300 transition-colors w-40"
                />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><MessageSquare className="w-4 h-4" /> Personal Reflection</label>
              <textarea value={editedBook.comments} onChange={e => setEditedBook(p => ({ ...p, comments: e.target.value }))} className="w-full p-6 rounded-[32px] border-2 border-gray-100 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50 outline-none h-40 resize-none bg-gray-50/50 transition-all text-gray-700" placeholder="Notes on writing, plot, or why it ended up in this tier..." />
            </div>
          </div>
        </div>

        <div className="p-8 border-t bg-gray-50/80 flex justify-end gap-4">
          <button onClick={onClose} className="px-8 py-3 rounded-2xl font-bold text-gray-400 uppercase text-[10px] tracking-widest hover:text-gray-600 transition-colors">Cancel</button>
          <button onClick={() => onSave(editedBook)} className="px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-white shadow-xl hover:scale-105 active:scale-95 transition-all" style={{ backgroundColor: accentColor }}>Update Log</button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  BookOpen, 
  Settings, 
  Plus, 
  Video,
  ChevronRight
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [goal, setGoal] = useState<number>(12);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const savedBooks = localStorage.getItem('shelfie_books');
    const savedTheme = localStorage.getItem('shelfie_theme');
    const savedColors = localStorage.getItem('shelfie_colors');
    const savedGoal = localStorage.getItem('shelfie_goal');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
    if (savedGoal) setGoal(parseInt(savedGoal));
  }, []);

  useEffect(() => {
    localStorage.setItem('shelfie_books', JSON.stringify(books));
    localStorage.setItem('shelfie_theme', activeTheme);
    localStorage.setItem('shelfie_colors', JSON.stringify(customColors));
    localStorage.setItem('shelfie_goal', goal.toString());
  }, [books, activeTheme, customColors, goal]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  // Derive all unique tags used across all books for suggestions
  const allUsedTags = useMemo(() => {
    const tags = new Set<string>();
    books.forEach(book => {
      book.tags?.forEach(tag => tags.add(tag));
    });
    return Array.from(tags).sort();
  }, [books]);

  const addBooks = useCallback((newBooks: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => {
    const preparedBooks: Book[] = newBooks.map(nb => ({
      ...nb,
      id: Math.random().toString(36).substr(2, 9),
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
      tags: [],
    }));
    setBooks(prev => [...prev, ...preparedBooks]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      // Standard completed tiers
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      // DNF counts only if > 80% progress
      if (book.tier === 'DNF' && (book.dnfProgress || 0) > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveAndReorderBook = (dragId: string, targetTier: TierId, targetBookId: string | null) => {
    setBooks(prev => {
      const result = [...prev];
      const draggedIndex = result.findIndex(b => b.id === dragId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = result.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = result.findIndex(b => b.id === targetBookId);
        result.splice(targetIndex, 0, draggedBook);
      } else {
        result.push(draggedBook);
      }
      return result;
    });
  };

  const handleDragStart = (id: string) => setDraggedBookId(id);
  const resetDrag = () => { setDraggedBookId(null); setDragOverTier(null); setDragOverBookId(null); };

  const onDropOnTier = (tierId: TierId) => {
    if (draggedBookId) moveAndReorderBook(draggedBookId, tierId, null);
    resetDrag();
  };

  const onDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDrag();
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookOpen className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">Shelfie</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-[10px] uppercase font-black opacity-40 tracking-widest">
              {goal > 0 ? 'Yearly Progress' : 'Total Read'}
            </span>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
              {goal > 0 && <span className="text-sm font-bold opacity-30">/ {goal}</span>}
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => setIsVeoOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Animate Cover"><Video className="w-5 h-5" /></button>
            <button onClick={() => setIsThemeOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Settings"><Settings className="w-5 h-5" /></button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-5 py-2 rounded-full text-white font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-4 h-4" /> Add Book
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-10 space-y-6">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={e => { e.preventDefault(); setDragOverTier(tier.id); }}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={() => onDropOnTier(tier.id)}
            className={`flex flex-col md:flex-row min-h-[180px] rounded-3xl overflow-hidden border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed shadow-xl bg-black/5' : 'border-transparent shadow-sm'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}10`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : 'transparent'
            }}
          >
            <div 
              className="md:w-36 p-6 flex flex-col items-center justify-center text-white font-black text-center"
              style={{ backgroundColor: currentColors[tier.id] }}
            >
              <span className="uppercase tracking-widest text-sm drop-shadow-sm">{tier.label}</span>
              <div className="mt-2 text-xs opacity-60 font-bold">{booksByTier[tier.id].length} Books</div>
            </div>

            <div className="flex-1 p-6 flex flex-wrap gap-6 min-h-[140px] items-start">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  onDragOver={e => { e.preventDefault(); e.stopPropagation(); setDragOverBookId(book.id); }}
                  onDragLeave={() => setDragOverBookId(null)}
                  onDrop={e => onDropOnBook(e, book.id, tier.id)}
                  onClick={() => setSelectedBook(book)}
                  className={`group w-24 sm:w-32 cursor-pointer transition-all ${draggedBookId === book.id ? 'opacity-20 scale-90 grayscale' : 'hover:-translate-y-2'} ${dragOverBookId === book.id ? 'ring-4 ring-offset-4 ring-white' : ''}`}
                  style={{ ['--tw-ring-color' as any]: currentColors.accent }}
                >
                  <div className="relative aspect-[2/3] rounded-xl overflow-hidden shadow-lg mb-2 bg-gray-200">
                    <img src={book.coverUrl || 'https://picsum.photos/120/180'} className="w-full h-full object-cover" alt={book.title} />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-2">
                      <ChevronRight className="w-5 h-5 text-white ml-auto" />
                    </div>
                  </div>
                  <h3 className="font-bold text-[10px] leading-tight truncate px-1">{book.title}</h3>
                  <p className="text-[9px] opacity-50 truncate px-1">{book.author}</p>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full flex items-center justify-center py-10 opacity-10 font-black text-2xl uppercase italic tracking-tighter flex-col gap-2">
                  <BookOpen className="w-12 h-12" />
                  <span>Empty Shelf</span>
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBooks} accentColor={currentColors.accent} />}
      {isThemeOpen && <ThemeManager activeTheme={activeTheme} setActiveTheme={setActiveTheme} customColors={customColors} setCustomColors={setCustomColors} goal={goal} setGoal={setGoal} onClose={() => setIsThemeOpen(false)} />}
      {isVeoOpen && <VeoAnimator onClose={() => setIsVeoOpen(false)} accentColor={currentColors.accent} />}
      {selectedBook && <BookModal book={selectedBook} globalTags={allUsedTags} onClose={() => setSelectedBook(null)} onSave={updateBook} onDelete={deleteBook} accentColor={currentColors.accent} />}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  MessageSquare, 
  Percent, 
  Plus, 
  History, 
  BookOpen, 
  Headphones, 
  Tablet,
  Check,
  Edit2,
  Tag as TagIcon
} from 'lucide-react';
import { Book, BookFormat, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  globalTags: string[];
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, globalTags, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book, tags: book.tags || [] });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);
  const [tagInput, setTagInput] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);
  const tagInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { if (editingTitle) titleInputRef.current?.focus(); }, [editingTitle]);
  useEffect(() => { if (editingAuthor) authorInputRef.current?.focus(); }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({ ...prev, sessions: [...prev.sessions, newSession] }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const addTag = (tagName: string) => {
    const cleanTag = tagName.trim();
    if (cleanTag && !editedBook.tags.includes(cleanTag)) {
      setEditedBook(prev => ({ ...prev, tags: [...prev.tags, cleanTag] }));
    }
    setTagInput('');
    setShowSuggestions(false);
  };

  const handleTagKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      e.preventDefault();
      addTag(tagInput);
    }
  };

  const removeTag = (tag: string) => {
    setEditedBook(prev => ({ ...prev, tags: prev.tags.filter(t => t !== tag) }));
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm(`Permanently remove "${editedBook.title}" from your library?`)) {
      onDelete(editedBook.id);
    }
  };

  const formatOptions: { value: BookFormat; icon: any; title: string }[] = [
    { value: 'Audiobook', icon: Headphones, title: 'Audiobook Format' },
    { value: 'Physical Book', icon: BookOpen, title: 'Physical Book Format' },
    { value: 'E-reader', icon: Tablet, title: 'E-reader/Digital Format' },
  ];

  const suggestedTags = globalTags.filter(t => 
    t.toLowerCase().includes(tagInput.toLowerCase()) && 
    !editedBook.tags.includes(t)
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b flex items-center justify-between bg-gray-50/50">
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 italic">Book Archive Detail</span>
          <div className="flex items-center gap-3">
            <button 
              onClick={handleDelete}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Delete Book from Library"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-all">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 flex flex-col md:flex-row gap-12">
          <div className="w-full md:w-80 flex flex-col gap-6">
            <div className="relative group">
              <img src={book.coverUrl || 'https://picsum.photos/320/480'} className="w-full aspect-[2/3] object-cover rounded-3xl shadow-2xl ring-8 ring-gray-50 bg-gray-100" alt={book.title} />
              <div className="absolute inset-0 rounded-3xl ring-1 ring-black/10 pointer-events-none"></div>
            </div>

            <div className="space-y-4">
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Title</label>
                {editingTitle ? (
                  <input ref={titleInputRef} className="w-full text-lg font-black bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.title} onChange={e => setEditedBook(p => ({ ...p, title: e.target.value }))} onBlur={() => setEditingTitle(false)} onKeyDown={e => e.key === 'Enter' && setEditingTitle(false)} />
                ) : (
                  <div onClick={() => setEditingTitle(true)} className="flex items-center gap-2 cursor-pointer font-black text-lg group-hover:text-indigo-600 transition-colors">{editedBook.title} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Author</label>
                {editingAuthor ? (
                  <input ref={authorInputRef} className="w-full text-sm font-bold bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.author} onChange={e => setEditedBook(p => ({ ...p, author: e.target.value }))} onBlur={() => setEditingAuthor(false)} onKeyDown={e => e.key === 'Enter' && setEditingAuthor(false)} />
                ) : (
                  <div onClick={() => setEditingAuthor(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500 group-hover:text-indigo-600 transition-colors">{editedBook.author} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
            </div>

            <div className="pt-6 border-t grid grid-cols-2 gap-2">
              {TIERS.map(t => (
                <button
                  key={t.id}
                  onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                  className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent shadow-lg' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                  style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                >{t.label}</button>
              ))}
            </div>
          </div>

          <div className="flex-1 space-y-8">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><History className="w-4 h-4" /> Reading Sessions</h3>
                <button onClick={addSession} className="px-4 py-2 rounded-full text-[10px] font-black uppercase text-white shadow-lg transition-transform hover:scale-105 active:scale-95" style={{ backgroundColor: accentColor }}>+ Session</button>
              </div>

              <div className="space-y-3">
                {editedBook.sessions.map(session => (
                  <div key={session.id} className="bg-gray-50/50 border-2 border-gray-100 rounded-2xl p-4 flex flex-wrap items-center gap-4 hover:border-indigo-100 transition-colors">
                    <div className="flex gap-2 bg-white p-1 rounded-xl border border-gray-100">
                      {formatOptions.map(opt => (
                        <button 
                          key={opt.value} 
                          title={opt.title}
                          onClick={() => updateSession(session.id, { format: opt.value })} 
                          className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-300 hover:text-gray-400'}`} 
                          style={{ backgroundColor: session.format === opt.value ? accentColor : '' }}
                        >
                          <opt.icon className="w-4 h-4" />
                        </button>
                      ))}
                    </div>
                    <div className="flex gap-2 flex-1 min-w-[150px]">
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">Start</span>
                        <input type="date" value={session.startDate} onChange={e => updateSession(session.id, { startDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">End</span>
                        <input type="date" value={session.endDate} onChange={e => updateSession(session.id, { endDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                    </div>
                    <button onClick={() => setEditedBook(p => ({ ...p, sessions: p.sessions.filter(s => s.id !== session.id) }))} className="text-gray-300 hover:text-red-400 transition-colors p-2"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="p-6 bg-red-50 rounded-3xl border-2 border-red-100 space-y-4 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center text-xs font-black uppercase tracking-widest text-red-500">
                  <div className="flex items-center gap-2"><Percent className="w-4 h-4" /> DNF Progress</div>
                  <span className="text-lg">{editedBook.dnfProgress || 0}%</span>
                </div>
                <input type="range" min="0" max="100" value={editedBook.dnfProgress || 0} onChange={e => setEditedBook(p => ({ ...p, dnfProgress: parseInt(e.target.value) }))} className="w-full h-3 bg-red-200 rounded-full appearance-none accent-red-600 cursor-pointer" />
                <div className="text-[10px] font-bold text-red-400 flex items-center gap-2">
                  <Check className={`w-3 h-3 transition-opacity ${editedBook.dnfProgress > 80 ? 'opacity-100' : 'opacity-20'}`} />
                  {editedBook.dnfProgress > 80 ? "Reached 80% - This book now counts towards your total read count!" : "Below 80% - Not counted in your yearly progress statistics."}
                </div>
              </div>
            )}

            <div className="space-y-4">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><TagIcon className="w-4 h-4" /> Tags (Genre, Year, Theme)</label>
              <div className="flex flex-wrap gap-2 p-4 bg-gray-50/50 rounded-3xl border-2 border-gray-100">
                {editedBook.tags?.map(tag => (
                  <span key={tag} className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white shadow-sm border border-gray-200 text-[10px] font-black uppercase text-gray-600 group">
                    {tag}
                    <button onClick={() => removeTag(tag)} className="text-gray-300 hover:text-red-500 transition-colors">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}

                <div className="relative">
                  <input 
                    ref={tagInputRef}
                    type="text" 
                    value={tagInput}
                    onChange={(e) => {
                      setTagInput(e.target.value);
                      setShowSuggestions(true);
                    }}
                    onFocus={() => setShowSuggestions(true)}
                    onKeyDown={handleTagKeyDown}
                    placeholder="Add tag..."
                    className="bg-transparent border-b border-gray-300 text-[10px] font-bold outline-none px-1 py-1 w-24 focus:border-indigo-400 transition-all uppercase"
                  />

                  {showSuggestions && tagInput && suggestedTags.length > 0 && (
                    <div className="absolute top-full left-0 z-50 mt-1 w-48 bg-white border border-gray-200 rounded-xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-top-1">
                      {suggestedTags.map(tag => (
                        <button 
                          key={tag}
                          onClick={() => addTag(tag)}
                          className="w-full px-4 py-2 text-left text-[10px] font-black uppercase hover:bg-indigo-50 transition-colors border-b last:border-0 border-gray-50"
                        >
                          {tag}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><MessageSquare className="w-4 h-4" /> Personal Reflection</label>
              <textarea value={editedBook.comments} onChange={e => setEditedBook(p => ({ ...p, comments: e.target.value }))} className="w-full p-6 rounded-[32px] border-2 border-gray-100 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50 outline-none h-40 resize-none bg-gray-50/50 transition-all text-gray-700" placeholder="Notes on writing, plot, or why it ended up in this tier..." />
            </div>
          </div>
        </div>

        <div className="p-8 border-t bg-gray-50/80 flex justify-end gap-4">
          <button onClick={onClose} className="px-8 py-3 rounded-2xl font-bold text-gray-400 uppercase text-[10px] tracking-widest hover:text-gray-600 transition-colors">Cancel</button>
          <button onClick={() => onSave(editedBook)} className="px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-white shadow-xl hover:scale-105 active:scale-95 transition-all" style={{ backgroundColor: accentColor }}>Update Log</button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

import React, { useState } from 'react';
import { Search, X, Loader2, Plus, BookOpen, Check } from 'lucide-react';

interface SearchResult {
  id: string;
  title: string;
  author: string;
  coverUrl: string;
}

interface SearchPanelProps {
  onClose: () => void;
  onAdd: (books: Omit<any, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => void;
  accentColor: string;
}

const SearchPanel: React.FC<SearchPanelProps> = ({ onClose, onAdd, accentColor }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(`https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(query)}&maxResults=10`);
      const data = await response.json();

      const formatted = (data.items || []).map((item: any) => ({
        id: item.id,
        title: item.volumeInfo.title,
        author: item.volumeInfo.authors?.[0] || 'Unknown Author',
        coverUrl: item.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:') || '',
      }));

      setResults(formatted);
      setSelectedIds(new Set()); // Reset selection on new search
    } catch (error) {
      console.error('Search failed', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) {
      next.delete(id);
    } else {
      next.add(id);
    }
    setSelectedIds(next);
  };

  const handleAddSelected = () => {
    const selectedBooks = results.filter(r => selectedIds.has(r.id));
    if (selectedBooks.length === 0) return;
    onAdd(selectedBooks);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-6 border-b flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-black text-gray-800 tracking-tight">Expand Library</h2>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Search & Select Multiple Books</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-gray-400" />
          </button>
        </div>

        <form onSubmit={handleSearch} className="p-6 bg-gray-50/50">
          <div className="relative">
            <input 
              type="text" 
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by title, author, or ISBN..."
              className="w-full pl-14 pr-4 py-4 rounded-3xl border-2 focus:ring-4 ring-indigo-50 outline-none transition-all shadow-inner text-lg font-medium"
              style={{ borderColor: `${accentColor}22` }}
              autoFocus
            />
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-7 h-7 text-gray-300" />
            <button 
              type="submit"
              className="absolute right-3 top-1/2 -translate-y-1/2 px-6 py-2 rounded-2xl text-white font-black uppercase text-xs tracking-widest shadow-lg transition-all active:scale-95"
              style={{ backgroundColor: accentColor }}
              disabled={loading}
            >
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Search'}
            </button>
          </div>
        </form>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {results.map(book => {
            const isSelected = selectedIds.has(book.id);
            return (
              <div 
                key={book.id} 
                onClick={() => toggleSelection(book.id)}
                className={`flex items-center gap-5 p-4 rounded-3xl border-2 cursor-pointer transition-all ${isSelected ? 'border-indigo-400 bg-indigo-50/50 shadow-md translate-x-2' : 'border-transparent hover:border-gray-100 hover:bg-gray-50'}`}
              >
                <div className="relative">
                  {book.coverUrl ? (
                    <img 
                      src={book.coverUrl} 
                      alt={book.title} 
                      className="w-20 h-28 object-cover rounded-2xl shadow-md border-2 border-white"
                    />
                  ) : (
                    <div className="w-20 h-28 bg-gray-100 rounded-2xl flex items-center justify-center border-2 border-white">
                      <BookOpen className="w-8 h-8 text-gray-300" />
                    </div>
                  )}
                  {isSelected && (
                    <div className="absolute -top-2 -right-2 bg-indigo-600 text-white rounded-full p-1.5 shadow-lg border-2 border-white animate-in zoom-in">
                      <Check className="w-4 h-4" strokeWidth={4} />
                    </div>
                  )}
                </div>
                <div className="flex-1">
                  <h3 className="font-black text-gray-900 leading-tight text-lg">{book.title}</h3>
                  <p className="text-sm font-medium text-gray-500 mt-1">{book.author}</p>
                </div>
              </div>
            );
          })}
          {!loading && results.length === 0 && query && (
            <div className="text-center py-16">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <Search className="w-10 h-10 text-gray-300" />
              </div>
              <p className="text-gray-400 font-bold">No results found for "{query}"</p>
            </div>
          )}
          {!query && (
            <div className="text-center py-16 opacity-30">
              <BookOpen className="w-16 h-16 mx-auto mb-4" />
              <p className="font-black text-xl uppercase tracking-tighter italic">Enter a keyword to begin</p>
            </div>
          )}
        </div>

        {selectedIds.size > 0 && (
          <div className="p-6 border-t bg-gray-50 flex items-center justify-between animate-in slide-in-from-bottom-5">
            <div className="flex flex-col">
              <span className="font-black text-gray-800 text-sm uppercase tracking-tight">{selectedIds.size} Selected</span>
              <button 
                onClick={() => setSelectedIds(new Set())}
                className="text-[10px] font-black uppercase text-indigo-500 text-left hover:underline"
              >
                Clear Selection
              </button>
            </div>
            <button 
              onClick={handleAddSelected}
              className="px-8 py-3 rounded-2xl text-white font-black uppercase text-xs tracking-[0.2em] shadow-xl transform transition-all active:scale-95 hover:scale-105"
              style={{ backgroundColor: accentColor }}
            >
              Add to Library
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchPanel;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  BookOpen, 
  Settings, 
  Plus, 
  Video,
  ChevronRight
} from 'lucide-react';
import { TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import VeoAnimator from './components/VeoAnimator';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [goal, setGoal] = useState<number>(12);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Dark Academia');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Dark Academia']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isVeoOpen, setIsVeoOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const savedBooks = localStorage.getItem('shelfie_books');
    const savedTheme = localStorage.getItem('shelfie_theme');
    const savedColors = localStorage.getItem('shelfie_colors');
    const savedGoal = localStorage.getItem('shelfie_goal');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
    if (savedGoal) setGoal(parseInt(savedGoal));
  }, []);

  useEffect(() => {
    localStorage.setItem('shelfie_books', JSON.stringify(books));
    localStorage.setItem('shelfie_theme', activeTheme);
    localStorage.setItem('shelfie_colors', JSON.stringify(customColors));
    localStorage.setItem('shelfie_goal', goal.toString());
  }, [books, activeTheme, customColors, goal]);

  const currentColors = useMemo(() => {
    return activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
  }, [activeTheme, customColors]);

  // Derive all unique tags used across the whole library for suggestions
  const globalUsedTags = useMemo(() => {
    const tagSet = new Set<string>();
    books.forEach(b => {
      b.tags?.forEach(t => tagSet.add(t));
    });
    return Array.from(tagSet).sort();
  }, [books]);

  const addBooks = useCallback((newBooks: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => {
    const preparedBooks: Book[] = newBooks.map((nb, index) => ({
      ...nb,
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${index}`,
      tier: 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
      tags: [],
    }));
    setBooks(prev => [...prev, ...preparedBooks]);
    setIsSearchOpen(false);
  }, []);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    // Robust delete: Filter the state directly
    setBooks(prevBooks => {
      const updated = prevBooks.filter(b => b.id !== id);
      console.log(`Deleted book with id: ${id}. Remaining: ${updated.length}`);
      return updated;
    });
    // Close modal
    setSelectedBook(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    return books.reduce((acc, book) => {
      if (['GOD', 'A', 'B', 'C'].includes(book.tier)) return acc + 1;
      if (book.tier === 'DNF' && (book.dnfProgress || 0) > 80) return acc + 1;
      return acc;
    }, 0);
  }, [books]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {
      TBR: [], GOD: [], A: [], B: [], C: [], DNF: []
    };
    books.forEach(b => map[b.tier].push(b));
    return map;
  }, [books]);

  const moveAndReorderBook = (dragId: string, targetTier: TierId, targetBookId: string | null) => {
    setBooks(prev => {
      const result = [...prev];
      const draggedIndex = result.findIndex(b => b.id === dragId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = result.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = result.findIndex(b => b.id === targetBookId);
        result.splice(targetIndex, 0, draggedBook);
      } else {
        result.push(draggedBook);
      }
      return result;
    });
  };

  const handleDragStart = (id: string) => setDraggedBookId(id);
  const resetDrag = () => { setDraggedBookId(null); setDragOverTier(null); setDragOverBookId(null); };

  const onDropOnTier = (tierId: TierId) => {
    if (draggedBookId) moveAndReorderBook(draggedBookId, tierId, null);
    resetDrag();
  };

  const onDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDrag();
  };

  return (
    <div 
      className="min-h-screen transition-colors duration-500 pb-20"
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookOpen className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">Shelfie</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-[10px] uppercase font-black opacity-40 tracking-widest">
              {goal > 0 ? 'Yearly Progress' : 'Total Read'}
            </span>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
              {goal > 0 && <span className="text-sm font-bold opacity-30">/ {goal}</span>}
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => setIsVeoOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Animate Cover"><Video className="w-5 h-5" /></button>
            <button onClick={() => setIsThemeOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Settings"><Settings className="w-5 h-5" /></button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-5 py-2 rounded-full text-white font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-4 h-4" /> Add Book
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-10 space-y-6">
        {TIERS.map(tier => (
          <div 
            key={tier.id}
            onDragOver={e => { e.preventDefault(); setDragOverTier(tier.id); }}
            onDragLeave={() => setDragOverTier(null)}
            onDrop={() => onDropOnTier(tier.id)}
            className={`flex flex-col md:flex-row min-h-[180px] rounded-3xl overflow-hidden border-2 transition-all ${dragOverTier === tier.id ? 'scale-[1.01] border-dashed shadow-xl bg-black/5' : 'border-transparent shadow-sm'}`}
            style={{ 
              backgroundColor: `${currentColors[tier.id]}10`, 
              borderColor: dragOverTier === tier.id ? currentColors[tier.id] : 'transparent'
            }}
          >
            <div 
              className="md:w-36 p-6 flex flex-col items-center justify-center text-white font-black text-center"
              style={{ backgroundColor: currentColors[tier.id] }}
            >
              <span className="uppercase tracking-widest text-sm drop-shadow-sm">{tier.label}</span>
              <div className="mt-2 text-xs opacity-60 font-bold">{booksByTier[tier.id].length} Books</div>
            </div>

            <div className="flex-1 p-6 flex flex-wrap gap-6 min-h-[140px] items-start">
              {booksByTier[tier.id].map(book => (
                <div 
                  key={book.id} 
                  draggable
                  onDragStart={() => handleDragStart(book.id)}
                  onDragOver={e => { e.preventDefault(); e.stopPropagation(); setDragOverBookId(book.id); }}
                  onDragLeave={() => setDragOverBookId(null)}
                  onDrop={e => onDropOnBook(e, book.id, tier.id)}
                  onClick={() => setSelectedBook(book)}
                  className={`group w-24 sm:w-32 cursor-pointer transition-all ${draggedBookId === book.id ? 'opacity-20 scale-90 grayscale' : 'hover:-translate-y-2'} ${dragOverBookId === book.id ? 'ring-4 ring-offset-4 ring-white' : ''}`}
                  style={{ ['--tw-ring-color' as any]: currentColors.accent }}
                >
                  <div className="relative aspect-[2/3] rounded-xl overflow-hidden shadow-lg mb-2 bg-gray-200">
                    <img src={book.coverUrl || 'https://picsum.photos/120/180'} className="w-full h-full object-cover" alt={book.title} />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-2">
                      <ChevronRight className="w-5 h-5 text-white ml-auto" />
                    </div>
                  </div>
                  <h3 className="font-bold text-[10px] leading-tight truncate px-1">{book.title}</h3>
                  <p className="text-[9px] opacity-50 truncate px-1">{book.author}</p>
                </div>
              ))}
              {booksByTier[tier.id].length === 0 && (
                <div className="w-full flex items-center justify-center py-10 opacity-10 font-black text-2xl uppercase italic tracking-tighter flex-col gap-2">
                  <BookOpen className="w-12 h-12" />
                  <span>Empty Shelf</span>
                </div>
              )}
            </div>
          </div>
        ))}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBooks} accentColor={currentColors.accent} />}
      {isThemeOpen && <ThemeManager activeTheme={activeTheme} setActiveTheme={setActiveTheme} customColors={customColors} setCustomColors={setCustomColors} goal={goal} setGoal={setGoal} onClose={() => setIsThemeOpen(false)} />}
      {isVeoOpen && <VeoAnimator onClose={() => setIsVeoOpen(false)} accentColor={currentColors.accent} />}
      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          globalTags={globalUsedTags}
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook} 
          onDelete={deleteBook} 
          accentColor={currentColors.accent} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  X, 
  Trash2, 
  MessageSquare, 
  Percent, 
  Plus, 
  History, 
  BookOpen, 
  Headphones, 
  Tablet,
  Check,
  Edit2,
  Tag as TagIcon,
  ChevronDown
} from 'lucide-react';
import { Book, BookFormat, ReadingSession } from '../types';
import { TIERS } from '../constants';

interface BookModalProps {
  book: Book;
  globalTags: string[];
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
}

const BookModal: React.FC<BookModalProps> = ({ book, globalTags, onClose, onSave, onDelete, accentColor }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book, tags: book.tags || [] });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);
  const [tagInput, setTagInput] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);
  const tagInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { if (editingTitle) titleInputRef.current?.focus(); }, [editingTitle]);
  useEffect(() => { if (editingAuthor) authorInputRef.current?.focus(); }, [editingAuthor]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({ ...prev, sessions: [...prev.sessions, newSession] }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const addTag = (tagName: string) => {
    const cleanTag = tagName.trim();
    if (cleanTag && !editedBook.tags.includes(cleanTag)) {
      setEditedBook(prev => ({ ...prev, tags: [...prev.tags, cleanTag] }));
    }
    setTagInput('');
    setShowSuggestions(false);
  };

  const handleTagKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      e.preventDefault();
      addTag(tagInput);
    }
  };

  const removeTag = (tag: string) => {
    setEditedBook(prev => ({ ...prev, tags: prev.tags.filter(t => t !== tag) }));
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm(`Are you sure you want to remove "${editedBook.title}" from your library? This action is permanent.`)) {
      // Use the original book ID to ensure consistency
      onDelete(book.id);
    }
  };

  const formatOptions: { value: BookFormat; icon: any; title: string }[] = [
    { value: 'Audiobook', icon: Headphones, title: 'Audiobook Format' },
    { value: 'Physical Book', icon: BookOpen, title: 'Physical Copy' },
    { value: 'E-reader', icon: Tablet, title: 'E-Reader / Digital' },
  ];

  const suggestedTags = globalTags.filter(t => 
    t.toLowerCase().includes(tagInput.toLowerCase()) && 
    !editedBook.tags.includes(t)
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b flex items-center justify-between bg-gray-50/50">
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 italic">Book Record Overview</span>
          <div className="flex items-center gap-3">
            <button 
              onClick={handleDelete}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Delete Book Record"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-all">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 flex flex-col md:flex-row gap-12">
          <div className="w-full md:w-80 flex flex-col gap-6">
            <div className="relative group">
              <img src={book.coverUrl || 'https://picsum.photos/320/480'} className="w-full aspect-[2/3] object-cover rounded-3xl shadow-2xl ring-8 ring-gray-50 bg-gray-100" alt={book.title} />
              <div className="absolute inset-0 rounded-3xl ring-1 ring-black/10 pointer-events-none"></div>
            </div>

            <div className="space-y-4">
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Title</label>
                {editingTitle ? (
                  <input ref={titleInputRef} className="w-full text-lg font-black bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.title} onChange={e => setEditedBook(p => ({ ...p, title: e.target.value }))} onBlur={() => setEditingTitle(false)} onKeyDown={e => e.key === 'Enter' && setEditingTitle(false)} />
                ) : (
                  <div onClick={() => setEditingTitle(true)} className="flex items-center gap-2 cursor-pointer font-black text-lg group-hover:text-indigo-600 transition-colors">{editedBook.title} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Author</label>
                {editingAuthor ? (
                  <input ref={authorInputRef} className="w-full text-sm font-bold bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.author} onChange={e => setEditedBook(p => ({ ...p, author: e.target.value }))} onBlur={() => setEditingAuthor(false)} onKeyDown={e => e.key === 'Enter' && setEditingAuthor(false)} />
                ) : (
                  <div onClick={() => setEditingAuthor(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500 group-hover:text-indigo-600 transition-colors">{editedBook.author} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
            </div>

            <div className="pt-6 border-t grid grid-cols-2 gap-2">
              {TIERS.map(t => (
                <button
                  key={t.id}
                  onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                  className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent shadow-lg' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                  style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                >{t.label}</button>
              ))}
            </div>
          </div>

          <div className="flex-1 space-y-8">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><History className="w-4 h-4" /> Reading Sessions</h3>
                <button onClick={addSession} className="px-4 py-2 rounded-full text-[10px] font-black uppercase text-white shadow-lg transition-transform hover:scale-105 active:scale-95" style={{ backgroundColor: accentColor }}>+ Session</button>
              </div>

              <div className="space-y-3">
                {editedBook.sessions.map(session => (
                  <div key={session.id} className="bg-gray-50/50 border-2 border-gray-100 rounded-2xl p-4 flex flex-wrap items-center gap-4 hover:border-indigo-100 transition-colors">
                    <div className="flex gap-2 bg-white p-1 rounded-xl border border-gray-100">
                      {formatOptions.map(opt => (
                        <button 
                          key={opt.value} 
                          onClick={() => updateSession(session.id, { format: opt.value })} 
                          className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-300 hover:text-gray-400'}`} 
                          style={{ backgroundColor: session.format === opt.value ? accentColor : '' }}
                          title={opt.title}
                        >
                          <opt.icon className="w-4 h-4" />
                        </button>
                      ))}
                    </div>
                    <div className="flex gap-2 flex-1 min-w-[150px]">
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">Start</span>
                        <input type="date" value={session.startDate} onChange={e => updateSession(session.id, { startDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">End</span>
                        <input type="date" value={session.endDate} onChange={e => updateSession(session.id, { endDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                    </div>
                    <button onClick={() => setEditedBook(p => ({ ...p, sessions: p.sessions.filter(s => s.id !== session.id) }))} className="text-gray-300 hover:text-red-400 transition-colors p-2"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="p-6 bg-red-50 rounded-3xl border-2 border-red-100 space-y-4 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center text-xs font-black uppercase tracking-widest text-red-500">
                  <div className="flex items-center gap-2"><Percent className="w-4 h-4" /> DNF Progress</div>
                  <span className="text-lg">{editedBook.dnfProgress || 0}%</span>
                </div>
                <input type="range" min="0" max="100" value={editedBook.dnfProgress || 0} onChange={e => setEditedBook(p => ({ ...p, dnfProgress: parseInt(e.target.value) }))} className="w-full h-3 bg-red-200 rounded-full appearance-none accent-red-600 cursor-pointer" />
                <div className="text-[10px] font-bold text-red-400 flex items-center gap-2">
                  <Check className={`w-3 h-3 transition-opacity ${editedBook.dnfProgress > 80 ? 'opacity-100' : 'opacity-20'}`} />
                  {editedBook.dnfProgress > 80 ? "Reached 80% - Counts towards total!" : "Below 80% - Not counted in progress goal."}
                </div>
              </div>
            )}

            <div className="space-y-4">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2">
                <TagIcon className="w-4 h-4" /> Tags (Genre, Year, Theme)
              </label>

              <div className="p-5 bg-gray-50/50 rounded-[32px] border-2 border-gray-100">
                <div className="flex flex-wrap gap-2 mb-4">
                  {editedBook.tags?.map(tag => (
                    <span key={tag} className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white shadow-sm border border-gray-200 text-[10px] font-black uppercase text-gray-600 group">
                      {tag}
                      <button onClick={() => removeTag(tag)} className="text-gray-300 hover:text-red-500 transition-colors">
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>

                <div className="relative">
                  <div className="flex items-center gap-2">
                    <input 
                      ref={tagInputRef}
                      type="text" 
                      value={tagInput}
                      onChange={(e) => {
                        setTagInput(e.target.value);
                        setShowSuggestions(true);
                      }}
                      onFocus={() => setShowSuggestions(true)}
                      onKeyDown={handleTagKeyDown}
                      placeholder="Add tag (e.g. 2026, Sci-Fi)..."
                      className="bg-transparent border-b border-gray-300 text-xs font-bold outline-none px-1 py-2 flex-1 focus:border-indigo-400 transition-all uppercase placeholder:text-gray-300"
                    />
                    <ChevronDown 
                      className={`w-4 h-4 text-gray-400 cursor-pointer transition-transform ${showSuggestions ? 'rotate-180' : ''}`}
                      onClick={() => setShowSuggestions(!showSuggestions)}
                    />
                  </div>

                  {showSuggestions && (tagInput || suggestedTags.length > 0) && (
                    <div className="absolute top-full left-0 z-50 mt-2 w-full max-h-48 bg-white border border-gray-200 rounded-2xl shadow-xl overflow-y-auto animate-in fade-in slide-in-from-top-1">
                      {suggestedTags.length > 0 ? suggestedTags.map(tag => (
                        <button 
                          key={tag}
                          onClick={() => addTag(tag)}
                          className="w-full px-5 py-3 text-left text-[10px] font-black uppercase hover:bg-indigo-50 transition-colors border-b last:border-0 border-gray-50 flex items-center justify-between"
                        >
                          {tag}
                          <Plus className="w-3 h-3 text-indigo-400" />
                        </button>
                      )) : tagInput ? (
                        <div className="px-5 py-3 text-[10px] font-bold text-gray-400 uppercase italic">
                          Press Enter to create new tag "{tagInput}"
                        </div>
                      ) : null}
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><MessageSquare className="w-4 h-4" /> Personal Reflection</label>
