                    />
                    <div className="opacity-10 font-black text-2xl uppercase italic tracking-tighter flex flex-col items-center gap-2">
                      <BookOpen className="w-12 h-12" />
                      <span>Empty Shelf</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBooks} accentColor={currentColors.accent} />}
      {isThemeOpen && (
        <ThemeManager 
          activeTheme={activeTheme} 
          setActiveTheme={setActiveTheme} 
          customColors={customColors} 
          setCustomColors={setCustomColors} 
          goal={goal} 
          setGoal={setGoal} 
          onClose={() => setIsThemeOpen(false)} 
          tiers={tiers}
          setTiers={setTiers}
          onExport={handleExport}
          onImport={handleImport}
        />
      )}
      {isInsightsOpen && <InsightsDashboard books={books} onClose={() => setIsInsightsOpen(false)} currentColors={currentColors} />}
      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          globalTags={globalUsedTags}
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook} 
          onDelete={deleteBook} 
          accentColor={currentColors.accent}
          tiers={tiers}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { X, Palette, Pipette, Target, Plus, Download, Upload, Trash2 } from 'lucide-react';
import { ThemePreset, ThemeColors, TierDefinition } from '../types';
import { THEME_PRESETS } from '../constants';

interface ThemeManagerProps {
  activeTheme: ThemePreset;
  setActiveTheme: (theme: ThemePreset) => void;
  customColors: ThemeColors;
  setCustomColors: (colors: ThemeColors) => void;
  goal: number;
  setGoal: (goal: number) => void;
  tiers: TierDefinition[];
  setTiers: (tiers: TierDefinition[]) => void;
  onExport: () => void;
  onImport: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onClose: () => void;
}

const ThemeManager: React.FC<ThemeManagerProps> = ({ 
  activeTheme, 
  setActiveTheme, 
  customColors, 
  setCustomColors, 
  goal,
  setGoal,
  tiers,
  setTiers,
  onExport,
  onImport,
  onClose 
