                  <div className="flex gap-1 opacity-80">
                    {tiers.slice(0, 4).map(t => (
                      <div key={t.id} className="w-4 h-4 rounded-full border border-black/5 shadow-sm" style={{ backgroundColor: (THEME_PRESETS[p] as any)[t.id] || t.color }} />
                    ))}
