import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  X, 
  Trash2, 
  MessageSquare, 
  Percent, 
  Plus, 
  History, 
  BookOpen, 
  Headphones, 
  Tablet,
  Check,
  Edit2,
  Tag as TagIcon,
  ChevronDown,
  Clock,
  TrendingUp
} from 'lucide-react';
import { Book, BookFormat, ReadingSession, TierDefinition } from '../types';

interface BookModalProps {
  book: Book;
  globalTags: string[];
  onClose: () => void;
  onSave: (book: Book) => void;
  onDelete: (id: string) => void;
  accentColor: string;
  tiers: TierDefinition[];
}

const BookModal: React.FC<BookModalProps> = ({ book, globalTags, onClose, onSave, onDelete, accentColor, tiers }) => {
  const [editedBook, setEditedBook] = useState<Book>({ ...book, tags: book.tags || [], pages: book.pages || 300 });
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingAuthor, setEditingAuthor] = useState(false);
  const [editingPages, setEditingPages] = useState(false);
  const [tagInput, setTagInput] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const titleInputRef = useRef<HTMLInputElement>(null);
  const authorInputRef = useRef<HTMLInputElement>(null);
  const pagesInputRef = useRef<HTMLInputElement>(null);
  const tagInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { if (editingTitle) titleInputRef.current?.focus(); }, [editingTitle]);
  useEffect(() => { if (editingAuthor) authorInputRef.current?.focus(); }, [editingAuthor]);
  useEffect(() => { if (editingPages) pagesInputRef.current?.focus(); }, [editingPages]);

  const addSession = () => {
    const newSession: ReadingSession = {
      id: Math.random().toString(36).substr(2, 9),
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      format: 'Physical Book',
    };
    setEditedBook(prev => ({ ...prev, sessions: [...prev.sessions, newSession] }));
  };

  const updateSession = (id: string, updates: Partial<ReadingSession>) => {
    setEditedBook(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, ...updates } : s)
    }));
  };

  const addTag = (tagName: string) => {
    const cleanTag = tagName.trim();
    if (cleanTag && !editedBook.tags.includes(cleanTag)) {
      setEditedBook(prev => ({ ...prev, tags: [...prev.tags, cleanTag] }));
    }
    setTagInput('');
    setShowSuggestions(false);
  };

  const handleTagKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      e.preventDefault();
      addTag(tagInput);
    }
  };

  const removeTag = (tag: string) => {
    setEditedBook(prev => ({ ...prev, tags: prev.tags.filter(t => t !== tag) }));
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm(`Are you sure you want to remove "${editedBook.title}" from your library? This action is permanent.`)) {
      onDelete(book.id);
    }
  };

  const readingStats = useMemo(() => {
    if (!editedBook.sessions.length) return null;

    const finishedSessions = editedBook.sessions.filter(s => s.startDate && s.endDate);
    const activeSessions = editedBook.sessions.filter(s => s.startDate && !s.endDate);

    let totalDays = 0;
    let pace = 0;

    if (finishedSessions.length > 0) {
      finishedSessions.forEach(s => {
        const start = new Date(s.startDate);
        const end = new Date(s.endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) || 1;
        totalDays += diffDays;
      });
      pace = Math.round((editedBook.pages * finishedSessions.length) / totalDays);
    } else if (activeSessions.length > 0) {
      const s = activeSessions[0];
      const start = new Date(s.startDate);
      const now = new Date();
      const diffTime = Math.abs(now.getTime() - start.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) || 1;
      const progress = editedBook.dnfProgress ? (editedBook.dnfProgress / 100) : 0.5;
      pace = Math.round((editedBook.pages * progress) / diffDays) || 1;
    }

    const estDaysLeft = pace > 0 ? Math.ceil(editedBook.pages / pace) : 0;

    return { pace, estDaysLeft };
  }, [editedBook]);

  const formatOptions: { value: BookFormat; icon: any; title: string }[] = [
    { value: 'Audiobook', icon: Headphones, title: 'Audiobook Format' },
    { value: 'Physical Book', icon: BookOpen, title: 'Physical Copy' },
    { value: 'E-reader', icon: Tablet, title: 'E-Reader / Digital' },
  ];

  const suggestedTags = globalTags.filter(t => 
    t.toLowerCase().includes(tagInput.toLowerCase()) && 
    !editedBook.tags.includes(t)
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[40px] w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl">
        <div className="p-6 border-b flex items-center justify-between bg-gray-50/50">
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 italic">Book Record Overview</span>
          <div className="flex items-center gap-3">
            <button 
              onClick={handleDelete}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Delete Book Record"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-all">
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-10 flex flex-col md:flex-row gap-12">
          <div className="w-full md:w-80 flex flex-col gap-6">
            <div className="relative group">
              <img src={book.coverUrl || 'https://picsum.photos/320/480'} className="w-full aspect-[2/3] object-cover rounded-3xl shadow-2xl ring-8 ring-gray-50 bg-gray-100" alt={book.title} />
              <div className="absolute inset-0 rounded-3xl ring-1 ring-black/10 pointer-events-none"></div>
            </div>

            <div className="space-y-4">
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Title</label>
                {editingTitle ? (
                  <input ref={titleInputRef} className="w-full text-lg font-black bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.title} onChange={e => setEditedBook(p => ({ ...p, title: e.target.value }))} onBlur={() => setEditingTitle(false)} onKeyDown={e => e.key === 'Enter' && setEditingTitle(false)} />
                ) : (
                  <div onClick={() => setEditingTitle(true)} className="flex items-center gap-2 cursor-pointer font-black text-lg group-hover:text-indigo-600 transition-colors">{editedBook.title} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Author</label>
                {editingAuthor ? (
                  <input ref={authorInputRef} className="w-full text-sm font-bold bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.author} onChange={e => setEditedBook(p => ({ ...p, author: e.target.value }))} onBlur={() => setEditingAuthor(false)} onKeyDown={e => e.key === 'Enter' && setEditingAuthor(false)} />
                ) : (
                  <div onClick={() => setEditingAuthor(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500 group-hover:text-indigo-600 transition-colors">{editedBook.author} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
              <div className="group bg-gray-50 p-3 rounded-2xl border border-gray-100">
                <label className="text-[9px] font-black uppercase text-gray-400">Total Pages</label>
                {editingPages ? (
                  <input ref={pagesInputRef} type="number" className="w-full text-sm font-bold bg-transparent outline-none border-b-2 border-indigo-200" value={editedBook.pages} onChange={e => setEditedBook(p => ({ ...p, pages: parseInt(e.target.value) || 0 }))} onBlur={() => setEditingPages(false)} onKeyDown={e => e.key === 'Enter' && setEditingPages(false)} />
                ) : (
                  <div onClick={() => setEditingPages(true)} className="flex items-center gap-2 cursor-pointer font-bold text-sm text-gray-500 group-hover:text-indigo-600 transition-colors">{editedBook.pages} <Edit2 className="w-3 h-3 text-gray-300" /></div>
                )}
              </div>
            </div>

            <div className="pt-6 border-t grid grid-cols-2 gap-2">
              {tiers.map(t => (
                <button
                  key={t.id}
                  onClick={() => setEditedBook(prev => ({ ...prev, tier: t.id }))}
                  className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${editedBook.tier === t.id ? 'text-white border-transparent shadow-lg' : 'text-gray-400 border-gray-100 hover:border-gray-200'}`}
                  style={{ backgroundColor: editedBook.tier === t.id ? accentColor : '' }}
                >{t.label}</button>
              ))}
            </div>
          </div>

          <div className="flex-1 space-y-8">
            {readingStats && (
              <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
                <div className="bg-gray-50 p-5 rounded-3xl border border-gray-100 flex items-center gap-4">
                  <div className="p-3 bg-white rounded-2xl shadow-sm" style={{ color: accentColor }}>
                    <TrendingUp className="w-6 h-6" />
                  </div>
                  <div>
                    <span className="block text-[8px] font-black uppercase text-gray-400 tracking-widest">Reading Pace</span>
                    <p className="text-xl font-black">{readingStats.pace} <span className="text-xs text-gray-400">pg/day</span></p>
                  </div>
                </div>
                <div className="bg-gray-50 p-5 rounded-3xl border border-gray-100 flex items-center gap-4">
                  <div className="p-3 bg-white rounded-2xl shadow-sm text-emerald-600">
                    <Clock className="w-6 h-6" />
                  </div>
                  <div>
                    <span className="block text-[8px] font-black uppercase text-gray-400 tracking-widest">Est. Completion</span>
                    <p className="text-xl font-black">{readingStats.estDaysLeft} <span className="text-xs text-gray-400">days left</span></p>
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><History className="w-4 h-4" /> Reading Sessions</h3>
                <button onClick={addSession} className="px-4 py-2 rounded-full text-[10px] font-black uppercase text-white shadow-lg transition-transform hover:scale-105 active:scale-95" style={{ backgroundColor: accentColor }}>+ Session</button>
              </div>

              <div className="space-y-3">
                {editedBook.sessions.map(session => (
                  <div key={session.id} className="bg-gray-50/50 border-2 border-gray-100 rounded-2xl p-4 flex flex-wrap items-center gap-4 hover:border-indigo-100 transition-colors">
                    <div className="flex gap-2 bg-white p-1 rounded-xl border border-gray-100">
                      {formatOptions.map(opt => (
                        <button 
                          key={opt.value} 
                          onClick={() => updateSession(session.id, { format: opt.value })} 
                          className={`p-2 rounded-lg transition-all ${session.format === opt.value ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-300 hover:text-gray-400'}`} 
                          style={{ backgroundColor: session.format === opt.value ? accentColor : '' }}
                          title={opt.title}
                        >
                          <opt.icon className="w-4 h-4" />
                        </button>
                      ))}
                    </div>
                    <div className="flex gap-2 flex-1 min-w-[150px]">
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">Start</span>
                        <input type="date" value={session.startDate} onChange={e => updateSession(session.id, { startDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                      <div className="flex-1">
                        <span className="block text-[8px] font-black uppercase text-gray-300 mb-0.5">End</span>
                        <input type="date" value={session.endDate} onChange={e => updateSession(session.id, { endDate: e.target.value })} className="text-[10px] p-1.5 rounded-lg border w-full outline-none focus:ring-1 focus:ring-indigo-200" />
                      </div>
                    </div>
                    <button onClick={() => setEditedBook(p => ({ ...p, sessions: p.sessions.filter(s => s.id !== session.id) }))} className="text-gray-300 hover:text-red-400 transition-colors p-2"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>

            {editedBook.tier === 'DNF' && (
              <div className="p-6 bg-red-50 rounded-3xl border-2 border-red-100 space-y-4 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center text-xs font-black uppercase tracking-widest text-red-500">
                  <div className="flex items-center gap-2"><Percent className="w-4 h-4" /> DNF Progress</div>
                  <span className="text-lg">{editedBook.dnfProgress || 0}%</span>
                </div>
                <input type="range" min="0" max="100" value={editedBook.dnfProgress || 0} onChange={e => setEditedBook(p => ({ ...p, dnfProgress: parseInt(e.target.value) }))} className="w-full h-3 bg-red-200 rounded-full appearance-none accent-red-600 cursor-pointer" />
                <div className="text-[10px] font-bold text-red-400 flex items-center gap-2">
                  <Check className={`w-3 h-3 transition-opacity ${editedBook.dnfProgress >= 80 ? 'opacity-100' : 'opacity-20'}`} />
                  {editedBook.dnfProgress >= 80 ? "Reached 80% or above - Counts towards total!" : "Below 80% - Not counted in progress goal."}
                </div>
              </div>
            )}

            <div className="space-y-4">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2">
                <TagIcon className="w-4 h-4" /> Tags (Genre, Year, Theme)
              </label>

              <div className="p-5 bg-gray-50/50 rounded-[32px] border-2 border-gray-100">
                <div className="flex flex-wrap gap-2 mb-4">
                  {editedBook.tags?.map(tag => (
                    <span key={tag} className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white shadow-sm border border-gray-200 text-[10px] font-black uppercase text-gray-600 group">
                      {tag}
                      <button onClick={() => removeTag(tag)} className="text-gray-300 hover:text-red-500 transition-colors">
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>

                <div className="relative">
                  <div className="flex items-center gap-2">
                    <input 
                      ref={tagInputRef}
                      type="text" 
                      value={tagInput}
                      onChange={(e) => {
                        setTagInput(e.target.value);
                        setShowSuggestions(true);
                      }}
                      onFocus={() => setShowSuggestions(true)}
                      onKeyDown={handleTagKeyDown}
                      placeholder="Add tag (e.g. 2026, Sci-Fi)..."
                      className="bg-transparent border-b border-gray-300 text-xs font-bold outline-none px-1 py-2 flex-1 focus:border-indigo-400 transition-all uppercase placeholder:text-gray-300"
                    />
                    <ChevronDown 
                      className={`w-4 h-4 text-gray-400 cursor-pointer transition-transform ${showSuggestions ? 'rotate-180' : ''}`}
                      onClick={() => setShowSuggestions(!showSuggestions)}
                    />
                  </div>

                  {showSuggestions && (tagInput || suggestedTags.length > 0) && (
                    <div className="absolute top-full left-0 z-50 mt-2 w-full max-h-48 bg-white border border-gray-200 rounded-2xl shadow-xl overflow-y-auto animate-in fade-in slide-in-from-top-1">
                      {suggestedTags.length > 0 ? suggestedTags.map(tag => (
                        <button 
                          key={tag}
                          onClick={() => addTag(tag)}
                          className="w-full px-5 py-3 text-left text-[10px] font-black uppercase hover:bg-indigo-50 transition-colors border-b last:border-0 border-gray-50 flex items-center justify-between"
                        >
                          {tag}
                          <Plus className="w-3 h-3 text-indigo-400" />
                        </button>
                      )) : tagInput ? (
                        <div className="px-5 py-3 text-[10px] font-bold text-gray-400 uppercase italic">
                          Press Enter to create new tag "{tagInput}"
                        </div>
                      ) : null}
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-black uppercase tracking-widest text-gray-400 flex items-center gap-2"><MessageSquare className="w-4 h-4" /> Personal Reflection</label>
              <textarea value={editedBook.comments} onChange={e => setEditedBook(p => ({ ...p, comments: e.target.value }))} className="w-full p-6 rounded-[32px] border-2 border-gray-100 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50 outline-none h-40 resize-none bg-gray-50/50 transition-all text-gray-700" placeholder="Notes on writing, plot, or why it ended up in this tier..." />
            </div>
          </div>
        </div>

        <div className="p-8 border-t bg-gray-50/80 flex justify-end gap-4">
          <button onClick={onClose} className="px-8 py-3 rounded-2xl font-bold text-gray-400 uppercase text-[10px] tracking-widest hover:text-gray-600 transition-colors">Cancel</button>
          <button onClick={() => onSave(editedBook)} className="px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest text-white shadow-xl hover:scale-105 active:scale-95 transition-all" style={{ backgroundColor: accentColor }}>Update Log</button>
        </div>
      </div>
    </div>
  );
};

export default BookModal;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  BookOpen, 
  Settings, 
  Plus, 
  ChevronRight, 
  Trash2, 
  BarChart2,
  Download,
  Upload
} from 'lucide-react';
import { DEFAULT_TIERS, THEME_PRESETS } from './constants';
import { Book, TierId, ThemePreset, ThemeColors, TierDefinition } from './types';
import SearchPanel from './components/SearchPanel';
import BookModal from './components/BookModal';
import ThemeManager from './components/ThemeManager';
import InsightsDashboard from './components/InsightsDashboard';

const App: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [tiers, setTiers] = useState<TierDefinition[]>(DEFAULT_TIERS);
  const [goal, setGoal] = useState<number>(12);
  const [activeTheme, setActiveTheme] = useState<ThemePreset>('Botanical Garden');
  const [customColors, setCustomColors] = useState<ThemeColors>(THEME_PRESETS['Botanical Garden']);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isThemeOpen, setIsThemeOpen] = useState(false);
  const [isInsightsOpen, setIsInsightsOpen] = useState(false);
  const [draggedBookId, setDraggedBookId] = useState<string | null>(null);
  const [dragOverTier, setDragOverTier] = useState<TierId | null>(null);
  const [dragOverBookId, setDragOverBookId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const savedBooks = localStorage.getItem('shelfie_books');
    const savedTiers = localStorage.getItem('shelfie_tiers');
    const savedTheme = localStorage.getItem('shelfie_theme');
    const savedColors = localStorage.getItem('shelfie_colors');
    const savedGoal = localStorage.getItem('shelfie_goal');

    if (savedBooks) setBooks(JSON.parse(savedBooks));
    if (savedTiers) setTiers(JSON.parse(savedTiers));
    if (savedTheme) setActiveTheme(savedTheme as ThemePreset);
    if (savedColors) setCustomColors(JSON.parse(savedColors));
    if (savedGoal) setGoal(parseInt(savedGoal));
  }, []);

  useEffect(() => {
    localStorage.setItem('shelfie_books', JSON.stringify(books));
    localStorage.setItem('shelfie_tiers', JSON.stringify(tiers));
    localStorage.setItem('shelfie_theme', activeTheme);
    localStorage.setItem('shelfie_colors', JSON.stringify(customColors));
    localStorage.setItem('shelfie_goal', goal.toString());
  }, [books, tiers, activeTheme, customColors, goal]);

  const currentColors = useMemo(() => {
    const themeColors = activeTheme === 'Custom' ? customColors : THEME_PRESETS[activeTheme];
    // Ensure all current tiers have a color in the current set
    const mergedColors = { ...themeColors };
    tiers.forEach(t => {
      if (!mergedColors[t.id]) {
        mergedColors[t.id] = t.color;
      }
    });
    return mergedColors;
  }, [activeTheme, customColors, tiers]);

  const themeClassName = useMemo(() => {
    return `theme-${activeTheme.toLowerCase().replace(/\s+/g, '-')}`;
  }, [activeTheme]);

  const globalUsedTags = useMemo(() => {
    const tagSet = new Set<string>();
    books.forEach(b => {
      b.tags?.forEach(t => tagSet.add(t));
    });
    return Array.from(tagSet).sort();
  }, [books]);

  const addBooks = useCallback((newBooks: Omit<Book, 'id' | 'tier' | 'sessions' | 'comments' | 'dnfProgress' | 'tags'>[]) => {
    const preparedBooks: Book[] = newBooks.map((nb, index) => ({
      ...nb,
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${index}`,
      tier: tiers[0]?.id || 'TBR',
      sessions: [],
      comments: '',
      dnfProgress: 0,
      tags: [],
      pages: nb.pages || 300,
    }));
    setBooks(prev => [...prev, ...preparedBooks]);
    setIsSearchOpen(false);
  }, [tiers]);

  const updateBook = useCallback((updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    setSelectedBook(null);
  }, []);

  const deleteBook = useCallback((id: string) => {
    setBooks(prevBooks => prevBooks.filter(b => b.id !== id));
    setSelectedBook(null);
    setDraggedBookId(null);
  }, []);

  const totalBooksRead = useMemo(() => {
    const godTier = tiers.find(t => t.label.toLowerCase().includes('god'))?.id;
    const aTier = tiers.find(t => t.label.toLowerCase().includes('a tier'))?.id;
    const bTier = tiers.find(t => t.label.toLowerCase().includes('b tier'))?.id;
    const cTier = tiers.find(t => t.label.toLowerCase().includes('c tier'))?.id;
    const dnfTier = tiers.find(t => t.label.toLowerCase().includes('dnf'))?.id;

    const readTiers = [godTier, aTier, bTier, cTier].filter(Boolean);

    return books.reduce((acc, book) => {
      if (readTiers.includes(book.tier)) return acc + 1;
      if (book.tier === dnfTier && (book.dnfProgress || 0) >= 80) return acc + 1;
      return acc;
    }, 0);
  }, [books, tiers]);

  const booksByTier = useMemo(() => {
    const map: Record<TierId, Book[]> = {};
    tiers.forEach(t => map[t.id] = []);
    books.forEach(b => {
      if (map[b.tier]) map[b.tier].push(b);
      else if (tiers.length > 0) {
        // Fallback for orphaned books
        map[tiers[0].id].push(b);
      }
    });
    return map;
  }, [books, tiers]);

  const moveAndReorderBook = (dragId: string, targetTier: TierId, targetBookId: string | null) => {
    setBooks(prev => {
      const result = [...prev];
      const draggedIndex = result.findIndex(b => b.id === dragId);
      if (draggedIndex === -1) return prev;

      const [draggedBook] = result.splice(draggedIndex, 1);
      draggedBook.tier = targetTier;

      if (targetBookId) {
        const targetIndex = result.findIndex(b => b.id === targetBookId);
        result.splice(targetIndex, 0, draggedBook);
      } else {
        result.push(draggedBook);
      }
      return result;
    });
  };

  const handleDragStart = (id: string) => setDraggedBookId(id);
  const resetDrag = () => { 
    setDraggedBookId(null); 
    setDragOverTier(null); 
    setDragOverBookId(null); 
  };

  const onDropOnTier = (tierId: TierId) => {
    if (draggedBookId) moveAndReorderBook(draggedBookId, tierId, null);
    resetDrag();
  };

  const onDropOnBook = (e: React.DragEvent, targetBookId: string, tierId: TierId) => {
    e.stopPropagation();
    if (draggedBookId && draggedBookId !== targetBookId) {
      moveAndReorderBook(draggedBookId, tierId, targetBookId);
    }
    resetDrag();
  };

  const handleCardDelete = (e: React.MouseEvent, id: string, title: string) => {
    e.stopPropagation();
    if (window.confirm(`Delete "${title}"?`)) {
      deleteBook(id);
    }
  };

  const getBookMetrics = (count: number) => {
    if (count <= 6) return { width: 128, gap: 'gap-6', showText: true };
    if (count <= 15) return { width: 100, gap: 'gap-4', showText: true };
    if (count <= 30) return { width: 80, gap: 'gap-3', showText: false };
    return { width: 64, gap: 'gap-2', showText: false };
  };

  const chunkArray = <T,>(arr: T[], size: number): T[][] => {
    const chunks: T[][] = [];
    for (let i = 0; i < arr.length; i += size) {
      chunks.push(arr.slice(i, i + size));
    }
    return chunks;
  };

  // Data Management
  const handleExport = () => {
    const data = {
      books,
      tiers,
      goal,
      activeTheme,
      customColors,
      version: '2.0'
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `shelfie-export-${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.books) setBooks(data.books);
        if (data.tiers) setTiers(data.tiers);
        if (data.goal) setGoal(data.goal);
        if (data.activeTheme) setActiveTheme(data.activeTheme);
        if (data.customColors) setCustomColors(data.customColors);
        alert('Library imported successfully!');
      } catch (err) {
        alert('Failed to import library. Please check the file format.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div 
      className={`min-h-screen transition-colors duration-500 pb-20 relative ${themeClassName}`}
      style={{ backgroundColor: currentColors.background, color: currentColors.text }}
    >
      <div className="shelf-texture" />

      <header className="sticky top-0 z-30 shadow-md p-4 backdrop-blur-md flex items-center justify-between border-b" 
              style={{ backgroundColor: `${currentColors.background}CC`, borderColor: `${currentColors.accent}33` }}>
        <div className="flex items-center gap-3">
          <BookOpen className="w-8 h-8" style={{ color: currentColors.accent }} />
          <h1 className="text-2xl font-bold tracking-tight">Shelfie</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-center">
            <span className="block text-[10px] uppercase font-black opacity-40 tracking-widest">
              {goal > 0 ? 'Yearly Progress' : 'Total Read'}
            </span>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black" style={{ color: currentColors.accent }}>{totalBooksRead}</span>
              {goal > 0 && <span className="text-sm font-bold opacity-30">/ {goal}</span>}
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={() => setIsInsightsOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="View Insights"><BarChart2 className="w-5 h-5" /></button>
            <button onClick={() => setIsThemeOpen(true)} className="p-2 rounded-full border hover:bg-black/5" style={{ borderColor: currentColors.accent, color: currentColors.accent }} title="Settings"><Settings className="w-5 h-5" /></button>
            <button 
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-5 py-2 rounded-full text-white font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all"
              style={{ backgroundColor: currentColors.accent }}
            >
              <Plus className="w-4 h-4" /> Add Book
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-10 space-y-12 relative z-10">
        {tiers.map(tier => {
          const tierBooks = booksByTier[tier.id] || [];
          const metrics = getBookMetrics(tierBooks.length);
          const bookChunks = chunkArray(tierBooks, 20);

          return (
            <div 
              key={tier.id}
              onDragOver={e => { e.preventDefault(); setDragOverTier(tier.id); }}
              onDragLeave={() => setDragOverTier(null)}
              onDrop={() => onDropOnTier(tier.id)}
              className={`flex flex-col md:flex-row rounded-3xl transition-all overflow-hidden ${dragOverTier === tier.id ? 'scale-[1.01] bg-black/5' : ''}`}
            >
              <div 
                className="md:w-36 p-6 flex flex-col items-center justify-center text-white font-black text-center shadow-xl relative z-20 shrink-0"
                style={{ backgroundColor: currentColors[tier.id] || tier.color }}
              >
                <span className="uppercase tracking-widest text-sm drop-shadow-sm">{tier.label}</span>
                <div className="mt-2 text-xs opacity-60 font-bold">{tierBooks.length} Books</div>
              </div>

              <div className="flex-1 flex flex-col gap-12 bg-black/[0.02]">
                {bookChunks.length > 0 ? (
                  bookChunks.map((chunk, chunkIdx) => (
                    <div key={`${tier.id}-shelf-${chunkIdx}`} className="shelf-row flex-1 p-6 flex flex-wrap items-end pb-8 relative">
                      <div 
                        className="shelf-ledge transition-all"
                        style={{ 
                          backgroundColor: currentColors[tier.id] || tier.color,
                          filter: 'brightness(0.7)',
                          borderBottom: `2px solid rgba(0,0,0,0.2)`
                        }}
                      />

                      <div className={`flex flex-wrap ${metrics.gap} w-full items-end`}>
                        {/* Fix: Explicitly type book as Book to resolve 'unknown' type property access errors */}
                        {chunk.map((book: Book) => (
                          <div 
                            key={book.id} 
                            draggable
                            onDragStart={() => handleDragStart(book.id)}
                            onDragOver={e => { e.preventDefault(); e.stopPropagation(); setDragOverBookId(book.id); }}
                            onDragLeave={() => setDragOverBookId(null)}
                            onDrop={e => onDropOnBook(e, book.id, tier.id)}
                            onDragEnd={resetDrag}
                            onClick={() => setSelectedBook(book)}
                            className={`group cursor-pointer transition-all ${draggedBookId === book.id ? 'opacity-20 scale-90 grayscale' : 'hover:-translate-y-4'} ${dragOverBookId === book.id ? 'ring-4 ring-offset-4 ring-white' : ''}`}
                            style={{ 
                              ['--tw-ring-color' as any]: currentColors.accent,
                              width: `${metrics.width}px`
                            }}
                          >
                            <div className="relative aspect-[2/3] rounded-lg overflow-hidden shadow-2xl mb-2 bg-gray-200 border-b-4 border-black/10">
                              <img src={book.coverUrl || 'https://picsum.photos/120/180'} className="w-full h-full object-cover" alt={book.title} />

                              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-between p-2">
                                <button 
                                  onClick={(e) => handleCardDelete(e, book.id, book.title)}
                                  className="bg-red-500/80 hover:bg-red-600 p-1 rounded-lg text-white ml-auto backdrop-blur-sm transition-all shadow-md active:scale-90"
                                  title="Delete Book"
                                >
                                  <Trash2 className="w-3.5 h-3.5" />
                                </button>
                                <ChevronRight className="w-5 h-5 text-white ml-auto" />
                              </div>
                            </div>
                            {metrics.showText && (
                              <div className="overflow-hidden">
                                <h3 className="font-bold text-[10px] leading-tight truncate px-1">{book.title}</h3>
                                <p className="text-[9px] opacity-50 truncate px-1">{book.author}</p>
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="shelf-row flex-1 p-6 flex items-center justify-center pb-8 relative min-h-[140px]">
                    <div 
                      className="shelf-ledge transition-all"
                      style={{ 
                        backgroundColor: currentColors[tier.id] || tier.color,
                        filter: 'brightness(0.7)',
                        borderBottom: `2px solid rgba(0,0,0,0.2)`
                      }}
                    />
                    <div className="opacity-10 font-black text-2xl uppercase italic tracking-tighter flex flex-col items-center gap-2">
                      <BookOpen className="w-12 h-12" />
                      <span>Empty Shelf</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </main>

      {isSearchOpen && <SearchPanel onClose={() => setIsSearchOpen(false)} onAdd={addBooks} accentColor={currentColors.accent} />}
      {isThemeOpen && (
        <ThemeManager 
          activeTheme={activeTheme} 
          setActiveTheme={setActiveTheme} 
          customColors={customColors} 
          setCustomColors={setCustomColors} 
          goal={goal} 
          setGoal={setGoal} 
          onClose={() => setIsThemeOpen(false)} 
          tiers={tiers}
          setTiers={setTiers}
          onExport={handleExport}
          onImport={handleImport}
        />
      )}
      {/* Fix: Pass tiers to InsightsDashboard */}
      {isInsightsOpen && <InsightsDashboard books={books} tiers={tiers} onClose={() => setIsInsightsOpen(false)} currentColors={currentColors} />}
      {selectedBook && (
        <BookModal 
          book={selectedBook} 
          globalTags={globalUsedTags}
          onClose={() => setSelectedBook(null)} 
          onSave={updateBook} 
          onDelete={deleteBook} 
          accentColor={currentColors.accent}
          tiers={tiers}
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useMemo } from 'react';
import { 
  X, 
  PieChart as PieIcon, 
  BarChart as BarIcon, 
  Layers, 
  Award, 
  Target, 
  Maximize2 
} from 'lucide-react';
import { 
  Chart, 
  registerables, 
  ChartConfiguration 
} from 'chart.js';
import { Book, ThemeColors, TierId, TierDefinition } from '../types';

Chart.register(...registerables);

interface InsightsDashboardProps {
  books: Book[];
  tiers: TierDefinition[];
  currentColors: ThemeColors;
  onClose: () => void;
}

const InsightsDashboard: React.FC<InsightsDashboardProps> = ({ books, tiers, currentColors, onClose }) => {
  const formatChartRef = useRef<HTMLCanvasElement>(null);
  const tierChartRef = useRef<HTMLCanvasElement>(null);
  const chartInstances = useRef<{ format?: Chart; tier?: Chart }>({});

  const stats = useMemo(() => {
    // Basic heuristics for "finished" based on common tier labels
    const finishedBooks = books.filter(b => ['GOD', 'A', 'B', 'C'].includes(b.tier) || (b.tier === 'DNF' && b.dnfProgress >= 80));
    const totalPages = finishedBooks.reduce((sum, b) => sum + (b.pages || 0), 0);

    const dnfBooks = books.filter(b => b.tier === 'DNF');
    const avgDnfProgress = dnfBooks.length > 0 
      ? Math.round(dnfBooks.reduce((sum, b) => sum + (b.dnfProgress || 0), 0) / dnfBooks.length) 
      : 0;

    const longestBook = books.length > 0 
      ? [...books].sort((a, b) => (b.pages || 0) - (a.pages || 0))[0] 
      : null;

    return { totalPages, avgDnfProgress, longestBook };
  }, [books]);

  const chartData = useMemo(() => {
    // Format distribution (based on all books sessions)
    const formatCounts: Record<string, number> = { 'Audiobook': 0, 'Physical Book': 0, 'E-reader': 0 };
    books.forEach(b => {
      b.sessions.forEach(s => {
        if (s.format) formatCounts[s.format]++;
      });
    });

    // Tier distribution - Dynamic based on current tiers
    const tierCounts: Record<TierId, number> = {};
    tiers.forEach(t => { tierCounts[t.id] = 0; });
    books.forEach(b => {
      if (tierCounts[b.tier] !== undefined) tierCounts[b.tier]++;
    });

    return { formatCounts, tierCounts };
  }, [books, tiers]);

  useEffect(() => {
    // Cleanup old charts to avoid 'unknown' type error from Object.values or re-initialization on canvas
    if (chartInstances.current.format) {
      chartInstances.current.format.destroy();
    }
    if (chartInstances.current.tier) {
      chartInstances.current.tier.destroy();
    }

    // Format Pie Chart
    if (formatChartRef.current) {
      const config: ChartConfiguration<'pie'> = {
        type: 'pie',
        data: {
          labels: Object.keys(chartData.formatCounts),
          datasets: [{
            data: Object.values(chartData.formatCounts),
            backgroundColor: [
              `${currentColors.accent}BB`,
              `${currentColors.GOD || '#E5989B'}BB`,
              `${currentColors.TBR || '#A3B18A'}BB`
            ],
            borderColor: '#ffffff',
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'bottom',
              labels: {
                color: currentColors.text,
                font: { weight: 'bold', size: 10 }
              }
            }
          }
        }
      };
      chartInstances.current.format = new Chart(formatChartRef.current, config);
    }

    // Tier Bar Chart - Use passed tiers prop instead of constant
    if (tierChartRef.current) {
      const labels = tiers.map(t => t.label);
      const data = tiers.map(t => chartData.tierCounts[t.id]);
      const colors = tiers.map(t => currentColors[t.id] || t.color);

      const config: ChartConfiguration<'bar'> = {
        type: 'bar',
        data: {
          labels,
          datasets: [{
            label: 'Books per Tier',
            data,
            backgroundColor: colors.map(c => `${c}CC`),
            borderRadius: 12,
            borderWidth: 0,
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: { color: `${currentColors.text}66`, font: { size: 10, weight: 'bold' } },
              grid: { display: false }
            },
            x: {
              ticks: { color: `${currentColors.text}88`, font: { size: 10, weight: 'bold' } },
              grid: { display: false }
            }
          },
          plugins: {
            legend: { display: false }
          }
        }
      };
      chartInstances.current.tier = new Chart(tierChartRef.current, config);
    }

    return () => {
      // Cleanup charts on unmount
      if (chartInstances.current.format) {
        chartInstances.current.format.destroy();
      }
      if (chartInstances.current.tier) {
        chartInstances.current.tier.destroy();
      }
    };
  }, [chartData, currentColors, tiers]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300">
      <div 
        className="w-full max-w-6xl max-h-[90vh] overflow-hidden flex flex-col rounded-[48px] shadow-2xl border border-white/10"
        style={{ backgroundColor: currentColors.background, color: currentColors.text }}
      >
        <div className="p-10 flex items-center justify-between border-b border-white/10">
          <div>
            <h2 className="text-4xl font-black tracking-tight">Reading Intelligence</h2>
            <p className="text-xs font-bold uppercase tracking-widest opacity-40 mt-1">Deep Analytics & Reading Pace Insights</p>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-black/5 rounded-full transition-colors border border-transparent hover:border-black/5">
            <X className="w-8 h-8 opacity-40" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-10">
          {/* Stat Grid */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="p-8 rounded-[32px] bg-white/5 border border-white/10 flex items-center gap-6">
              <div className="p-4 rounded-2xl shadow-sm" style={{ backgroundColor: `${currentColors.accent}20`, color: currentColors.accent }}>
                <Maximize2 className="w-8 h-8" />
              </div>
              <div>
                <span className="block text-[10px] font-black uppercase tracking-widest opacity-40">Total Pages Read</span>
                <p className="text-3xl font-black">{stats.totalPages.toLocaleString()}</p>
              </div>
            </div>

            <div className="p-8 rounded-[32px] bg-white/5 border border-white/10 flex items-center gap-6">
              <div className="p-4 rounded-2xl shadow-sm" style={{ backgroundColor: `${currentColors.DNF || '#582F0E'}20`, color: currentColors.DNF || '#582F0E' }}>
                <Target className="w-8 h-8" />
              </div>
              <div>
                <span className="block text-[10px] font-black uppercase tracking-widest opacity-40">Avg DNF Progress</span>
                <p className="text-3xl font-black">{stats.avgDnfProgress}%</p>
              </div>
            </div>

            <div className="p-8 rounded-[32px] bg-white/5 border border-white/10 flex items-center gap-6">
              <div className="p-4 rounded-2xl shadow-sm" style={{ backgroundColor: `${currentColors.GOD || '#E5989B'}20`, color: currentColors.GOD || '#E5989B' }}>
                <Award className="w-8 h-8" />
              </div>
              <div className="flex-1 overflow-hidden">
                <span className="block text-[10px] font-black uppercase tracking-widest opacity-40">Longest Book</span>
                <p className="text-lg font-black truncate">{stats.longestBook?.title || 'None'}</p>
                <p className="text-xs font-bold opacity-30">{stats.longestBook?.pages || 0} Pages</p>
              </div>
            </div>
          </div>

          {/* Charts Row */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            <div className="p-10 rounded-[40px] bg-white/5 border border-white/10 flex flex-col">
              <h3 className="text-xs font-black uppercase tracking-widest opacity-40 mb-8 flex items-center gap-2">
                <PieIcon className="w-4 h-4" /> Format Distribution
              </h3>
              <div className="flex-1 min-h-[300px] relative">
                <canvas ref={formatChartRef}></canvas>
              </div>
            </div>

            <div className="p-10 rounded-[40px] bg-white/5 border border-white/10 flex flex-col">
              <h3 className="text-xs font-black uppercase tracking-widest opacity-40 mb-8 flex items-center gap-2">
                <BarIcon className="w-4 h-4" /> Tier Ranking Spread
              </h3>
              <div className="flex-1 min-h-[300px] relative">
                <canvas ref={tierChartRef}></canvas>
              </div>
            </div>
          </div>

          {/* Summary Quote / Action */}
          <div className="p-12 rounded-[40px] text-center bg-gradient-to-br from-black/5 to-transparent border border-white/10">
            <Layers className="w-12 h-12 mx-auto mb-6 opacity-20" />
            <p className="text-2xl font-black italic max-w-2xl mx-auto opacity-60 leading-relaxed">
              "A reader lives a thousand lives before he dies... The man who never reads lives only one."
            </p>
            <p className="mt-4 text-[10px] font-black uppercase tracking-[0.4em] opacity-30">— George R.R. Martin</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default InsightsDashboard;
